import { fingerprint } from './api-hash'
import type { Locale } from './locales'

/**
 * The sentence under each example, in Chinese.
 *
 * The English lives in a JSDoc block above `export function Example` in the
 * example file itself, and `generate.mjs` reads it from there. The obvious
 * place for the Chinese was therefore a second block in that same file, beside
 * the code it describes — and that argument is real. Prose kept next to its
 * subject is why the English is there in the first place, and an author editing
 * an example would have both sentences on screen at once.
 *
 * It is not what this file does, for one reason that outweighs it: locality is
 * a prompt, not a check. Nothing fails when the English sentence is revised and
 * the Chinese beside it is not, and these sentences are exactly the kind that
 * get revised — they name pixel values, WCAG criteria, prop names and default
 * values. When `sm` stops being 36px, the English is corrected and the Chinese
 * quietly becomes a lie about a measurement. The repository has already been
 * bitten by this: the same fingerprint check on `api.ts` caught three Chinese
 * entries that had been wrong on the live site for weeks, and those were
 * translations a reviewer could have read against their source too.
 *
 * So the Chinese lives here, keyed the way the canvas keys an example —
 * `Directory/example-id` — and each entry records a fingerprint of the English
 * it was made from. `examples.test.ts` fails the build when the two no longer
 * match, which turns the drift from something a reader discovers into something
 * a commit cannot get past. What is given up is proximity; what is bought is
 * that a wrong translation cannot ship quietly. The API reference made the same
 * trade for the same reason.
 *
 * Plain text, deliberately: these render into a bare `<p>`, not through
 * `<Prose>`, so a backtick or a pair of asterisks reaches the page as
 * literal characters.
 */
export interface ExampleCopy {
  /** `fingerprint()` of the English source this was translated from. */
  hash: string
  zh: string
}

export const EXAMPLE_ZH: Record<string, ExampleCopy> = {
  // ─── Actions ───
  "Button/01-variants": { hash: '68d6b1c4', zh: "四个 variant，按它们争夺注意力的顺序排开。variant 默认是 primary，所以一屏只留一个，其余控件一律给 secondary 或 ghost；danger 是一种状态、不是一档强调，把它花在「只是重要」的东西上，等到真有什么是破坏性的时候，页面上就再没有东西读起来像破坏性的了。" },
  "Button/02-sizes": { hash: 'cb8ddb44', zh: "同一个 variant 下的三个尺寸，于是变的只有那个盒子。几乎永远该拿 md：sm 在默认密度下是 36px，低于 md 自己就能达到的 44px，所以拿它拼出来的工具栏，是一排拇指按不中的目标（WCAG 2.5.5）——而 lg 是留给这一页真正在讲的那一个动作的。" },
  "Button/03-states": { hash: '324ec2bf', zh: "一个正在飞行中的控件、一个被关掉的控件，以及一个把快捷键写在脸上的控件。用 loading，别自己手动换文案：它一步就把文案留住、把 aria-busy 设上、把点击挡掉，于是这个盒子不会在刚按中它的指针底下塌掉。那枚键帽是真的文字，会并进无障碍名称里，所以只有真的绑了这个键时才写它。" },
  "Button/04-icon-only": { hash: '8c37df88', zh: "一个方形控件，只有一个图形、没有文字，用在文字只会把这一行已经说过的话再说一遍的工具栏里。iconOnly 不会在后面留下任何文字形状的东西，所以 aria-label 在这里不是可选项——一个没有它的图标按钮会被播报成「一个按钮」，没有名字，而这正是一套设计系统交付一个没人能用的控件最常见的方式。" },
  "FloatingIconButton/01-back-to-top": { hash: 'dbe6cb44', zh: "一个页面级的可用手段，读者一路往下滚它都还够得着。position 是必填的、没有默认值，取值按阅读顺序分 start 和 end——end 在英文里是右边，在阿拉伯文里是左边。label 会被设成 aria-label，永远不渲染出来，所以读屏软件拿到的是名字，而看得见的读者只拿到那个图形：要么挑一个自身就承载含义的图形，要么用 Tooltip 包起来。真实使用时这个控件固定在视口上；这里外面那个盒子是为了让预览诚实，因为一个 fixed 元素落在做过 transform 的祖先里，会钉在那个祖先上，而不是屏幕上。" },
  "FloatingIconButton/02-a-tooltip-name": { hash: '8c0b1ce6', zh: "label 就是 aria-label，别无其他：它只为读屏软件命名这个控件，不为任何别人，所以一个并不通用的图形，还得把那个词也放到屏幕上。Tooltip 就是办法，但有一条在这里比在任何地方都要紧的注意事项——Radix 遇到触摸指针会提前返回，所以这个提示在手机上永远不会打开，而手机恰恰是浮动控件最常成为视野里唯一可用手段的地方。提示和 label 是同一个字符串，所以两者不会各走各的（WCAG 2.5.3）。" },
  "FloatingIconButton/03-two-corners": { hash: '764a0000', zh: "两个角落，以及为什么放不下第三个。start 被抬到 5rem，end 停在 1.5rem，这正是一对控件需要的净空——何况这些角落早就在跟 cookie 条、聊天入口，以及浏览器塞在阅读起点那个角上的东西抢地方，这也是为什么抬高的是 start 那一个。控件是 --control-h-md 的正方形：默认密度下 44px，正好压在指针目标的下限上，data-density=\"compact\" 下是 36px。把上面那个密度开关拨过去，这个拇指不用看就去按的控件，就掉到下限以下八个像素。" },

  // ─── Forms ───
  "Checkbox/01-default": { hash: 'd342c039', zh: "一个「全选」表头，管着它所概括的那些行。选中了一部分、又不是全部，就是 indeterminate 状态，而它必须通过受控的 checked 传进来：那个字形是从 props.checked 挑出来的，所以一个非受控的框永远画不出那道横杠，报出来的还正好是事实的反面。这个状态的意思是「它下面的东西里有一些」，所以它只属于表头——一个叶子节点画出横杠，是在宣称一个它自己的值根本承载不了的状态。注意那些文字：控件自己一个字都不渲染，所以那些词、以及它们给出的点击区域，是调用处的活儿。" },
  "Checkbox/02-with-descriptions": { hash: 'c70fbd58', zh: "框、名字，以及那句说明「答应下来到底要付什么代价」的话——三样都在 label 里面，于是整行都是点击目标，而不是一个 18px 的方块，而且那句话是无障碍名称的一部分。这既是把细节放进去而不是摆在旁边的理由，也是把它压到一个从句以内的理由：每次读到这一行，它都会被念出来。各行按第一行文字对齐，因为一个对着两行文字居中的框，会从它所属的那个词旁边飘走。这些是表单保存时才生效的；当场就生效的设置是 Switch。" },
  "Checkbox/03-inside-a-form": { hash: 'd04efc73', zh: "一个提交出去的表单真正携带的东西。没勾的框根本不发送任何条目——不是 false，是什么都没有——所以一个读者特意清掉的字段，和一个压根没渲染过的字段，到了服务端一模一样，默认值只能在那边定，不能从载荷里推。把两个都取消勾选再保存，看着那两个键消失。每个框都得有 name 才发得出东西；value 是它开着的时候发送的内容。" },
  "Combobox/01-default": { hash: '8f6ae16d', zh: "七个天体，藏在一个「匹配得比印出来的多」的过滤器后面：输入 compact，会浮上来两个，尽管两个都没写这个词。可读的文字放 label，其他值得参与匹配的放 keywords——cmdk 同时也拿选项的 value 去打分，所以一个用 UUID 做键的列表，是在拿一个读者永远不会去敲的字符串排名次。高亮是靠 aria-activedescendant 移动的，焦点一直留在输入框里，这正是输入的文字始终可编辑的原因。这里什么都没有虚拟化：每个选项在打开时就全部渲染出来，并一直留在过滤器后面，所以一千个选项是 DOM 的开销，不是搜索的开销。" },
  "Combobox/02-multiple": { hash: '7466dd70', zh: "一次选好几个，触发器给的是概括而不是罗列：两个标签，然后一个计数。正是这个阈值挡住了字段随着它的值一起长大、每选一次就把表单重排一遍。选的过程中面板不关，而人字形旁边那个清除控件是一个带 button role 的 span——在触发器里真的嵌一个 button 是非法标记，浏览器会把它整个挪出这个字段。触发器由它的标签和它的概括共同命名——aria-labelledby 同时指向两者——所以读屏软件听到的是「Tags 已选 3 项」，而不是只有标签，那个计数不打开面板也能确认。" },
  "Combobox/03-controlled-and-cleared": { hash: 'e4cf91f4', zh: "一个受控的 Combobox，以及把它清空的唯一正确做法。「什么都没选」要拼成空字符串：value={undefined} 恰恰是这个组件用来判定自己是「非受控」的那个信号，所以那样清空等于把它自己的状态还给了它，从此它就不再跟着父组件走了——这个 bug 表现出来，是一个从第一次之后就无视每一次重置的选择器。下面那行读数就是这份状态，也正是把它拎到外面来的意义。" },
  "DatePicker/01-default": { hash: 'b03717a5', zh: "一个触发器，加一个装在 Popover 里的 Calendar，而且刻意不是一个挂着日历的文本输入框：敲进去的日期需要一个格式，而 03/04 在一个国家是三月四号，在下一个国家是四月三号。触发器按访客自己的地区习惯印出所选日期，也是同一个理由。真正打字更快的地方——比如往回好几年的一个日期——月份和年份是下拉框，那条路径还在，只是没了歧义。" },
  "DatePicker/02-range": { hash: 'a32570be', zh: "两个月并排，因为跨月的区间才是常见情况，而为了同时看到两头来回翻页，正是区间选择器让人累的地方。两端都选定之前，面板不关——一个区间在拿到第二个日期之前还不成其为一个值——而只定了一端的时候，触发器印的是「起 – …」，于是一个答了一半的区间会在收起的控件上就说明这件事，而不是装作已经完成。这个半成状态是合法的，所以读第二个日期之前先校验：一个提前关掉面板的读者，会把它留成 undefined。" },
  "DatePicker/03-presets": { hash: 'ac79b93d', zh: "网格旁边那条边栏——单日选择器上默认关，区间选择器上默认开，因为「最近 30 天」几乎就是区间选择器被问到的全部，而单个日期通常是某个具体的日子。它们是普通按钮，不是菜单，所以它们设的值和网格设的是同一个，Tab 也和网格在同一轮里过。每个快捷方式都是在点击那一刻算出来的，不是渲染时：一份只构建一次的列表，会把「今天」冻结在页面加载的那一刻。" },
  "DatePicker/04-blocked-dates": { hash: '0577f089', zh: "disabledDates 一路透传给日历：这里拒掉了过去的日子和周末，网格不会让你提交这样一个日期。注意旁边没有快捷方式边栏——那些快捷方式是把自己的值直接塞进网格用的同一个 setter，从来不会拿 disabledDates 检验，所以在这套规则旁边摆一条边栏，它会痛快地提交一个网格自己都拒绝的星期天。两个都要，就自己挨个检查每个快捷方式。另外，要用 disabledDates 而不是 disabled：disabled 会把触发器从 tab 顺序里拿走、把它的指针事件挡掉，而触发器是唯一印出所选日期的地方。" },
  "Field/01-states": { hash: '9ba973a8', zh: "一行会长成的四种样子：必填、答错了、一个必须自己报名字的控件，以及一个更长的回答。hint 和 error 是同一个槽位、不是两条堆起来的消息——一个字段错了的时候，该读的是它错在哪，所以提示会让开，而不是排在错误下面。Region 那一行故意把 Region 说了两遍：Radix 的 select 根节点不渲染任何 DOM 节点，所以 label 绑不到东西上，控件自己的 label 属性是它唯一的名字。" },
  "Field/02-one-message-slot": { hash: '1616cb9c', zh: "hint 和 error 是同一行，而错误赢。把 @ 删掉，看着那个格式说明在读者最需要它的那一刻消失——这也正是为什么下面那条错误要把「一个好答案长什么样」重说一遍，而不是只说一句不行。传了 error，这一行需要的 invalid 状态也就齐了：字段会给 input 加上 aria-invalid，而 Input 两种拼法都认，所以再加一个 invalid，等于把同一个事实从两个可能互相打架的地方各说一遍。" },
  "Field/03-naming-a-group": { hash: 'f2cca82d', zh: "把 Field 套在 RadioGroup 外面，只会把那些字画出来、却什么都没绑上：这个组的根是一个 div，而 htmlFor 只够得着可加标签的元素，于是点那些字什么也不会发生，这个组被播报出来时压根没有名字。同样那些字要以 aria-label 的形式落到组上，那才是读屏软件真正会读的东西。ToggleGroup 需要同样的处理，而 Select、Combobox、DatePicker 和 Slider 各自出于同一个理由，都收一个必填的 label。" },
  "Field/04-a-stable-id": { hash: 'a18c6ad3', zh: "htmlFor，以及控件上那个同样的 id。不写它，字段会生成一个 useId 的值——一个这一行之外没人猜得到的字符串——于是一个表单库、一个测试，或者下面那个按钮，都没有办法够到那个出错的输入框。只要这一行之外有东西必须指名道姓地找这个控件，就传它；在这一行内部，生成的 id 已经把活干了。" },
  "Input/01-default": { hash: 'ae30ac91', zh: "静止、非法、禁用。invalid 会用 --danger 画边框、并设上 aria-invalid，仅此而已——边框只说「有什么不对」，从不说是什么不对，所以一个放在带错误消息的 Field 之外的 invalid 输入框，就是一个红盒子，后面什么理由都没接。这里每一个都带着 aria-label，因为它们在这儿是孤零零站着的；放进表单里，那是 Field 的活，而 placeholder 永远不是名字，因为任何人一开始打字它就走了。" },
  "Input/02-types-and-autofill": { hash: '08ef5ab7', zh: "type、inputMode 和 autoComplete，每一行都写全。一个什么都不说的 Input 就是 type=\"text\"：于是邮箱字段拿到的是一个上面没有 @ 的电话键盘，也完全没有浏览器校验；而一个从不说 current-password 的密码字段，是密码管理器会填错值、且没有任何浏览器提出要帮你保存的那一种。手机号那一行用的是 type=\"tel\" 而不是 type=\"number\"——number 是给数量用的，它会把前导零丢掉，还会在滚轮底下改掉自己的值。" },
  "Input/03-read-only": { hash: '15dcdd11', zh: "同一个意思，锁法有两种。readOnly 让字段留在 tab 顺序里、也留在提交出去的表单数据里；disabled 把它从两边都拿走，于是服务端对一个读者明明看得见的字段一无所知——只要这个值是真的、只是不给改，就该拿 readOnly。这里没有任何样式画 readOnly：控件只在 :disabled 时才变淡，所以一个只读字段和一个可编辑字段像素级一致，只能靠提示文字说明。Tooltip 也补不上禁用那一行的这个缺口，因为一个 disabled 的输入框收不到 hover。" },
  "NativeSelect/01-default": { hash: '55676d6c', zh: "平台自己的选择器，在能改的范围内改了样式：appearance-none 去掉操作系统那个箭头，旁边这个人字形是我们的，所以列表打开时它不会翻转、也不会挪位。它做不到的，是打开之后还像这套系统——那些选项是操作系统画的，一个 token 都不带，这也正是为什么它是逃生口，而 Select 才是默认。真正该拿它的地方，是平台确实更强的场合：手机上一个很长的列表、一个必须在没有 JavaScript 时也能工作的表单、一个在计较最后一千字节的页面。" },
  "NativeSelect/02-a-placeholder-option": { hash: 'b47cb91b', zh: "一个空的首项，禁用，再让 defaultValue 指向它。一个没人碰过的 select，第一项本来就已经是选中的，所以一个开在 Australia 上的列表，会替一个从没看过这个字段的读者提交 Australia。把那一项命名成「请选择国家」只是把问题挪了个地方：它会被播报成一个可选的取值，而且一个没人动过的表单发出去的还是它。名字应该在 Field 上。注意 required 也写在 select 上了——Field 自己的 required 是那颗星号和 aria-required，从不会落到控件的属性上，所以这里让浏览器真正拒绝提交的是 select 上的这一个。" },
  "NativeSelect/03-option-groups": { hash: '6bfc602c', zh: "optgroup 是操作系统的选择器唯一真会渲染出来的结构，而且它没有 SelectLabel 给 Select 的那种降级样式——所以它就是一个长的原生列表保持可扫读的方式。宽度来自父元素，而不是 className：className 落在 select 自己身上，而人字形是相对它外面那层容器定位的，所以那样收窄一个字段，会把它自己的箭头孤零零地丢在这一行的最远端。" },
  "RadioGroup/01-default": { hash: '7d9c1866', zh: "三个选项，一个 tab 停靠点：方向键在它们之间移动，这是 ARIA 的 radiogroup 模式，也是一摞手搓单选框通常会丢掉的那一半。aria-label 不是可选项——根节点是一个 div，所以 htmlFor、包括 Field 画出来的那一个，都绑不到东西上，这个组被播报出来时会完全没有名字。defaultValue 同样要紧：这里选择跟着焦点走，所以一个空着开场的组，会替任何一个在去下一个字段路上用方向键掠过它的人，提交一个答案。" },
  "RadioGroup/02-options-with-detail": { hash: '0b41206a', zh: "选项里面的第二行，价格或者额度这种真正决定选择的东西写在这儿。RadioGroupItem 自己的 label 会把交给它的东西整个包住，所以那点细节在点击目标里面、也在无障碍名称里面——把它压到那个一锤定音的事实上，因为每次读到这个选项，它都会被一起念出来。各行按第一行文字对齐，因为一个对着两行文字居中的圆点，会从它所属的那个名字旁边飘走。" },
  "RadioGroup/03-a-way-back": { hash: '4698afde', zh: "「任意时间」是那个让其余选项保持可选的选项。单选一旦选中就没有退回「什么都没选」的路——再点一次不行，键盘上也不行——所以一个没有明确出口的筛选器，读者进得去、出不来。同一个道理也否掉了「用禁用某个选项来表示这里没有」：漫游焦点会把一个禁用选项整个跳过，于是用键盘的读者根本不会知道它存在。把它去掉，然后在 Field 的提示里说明原因。" },
  "Select/01-default": { hash: '1b72e680', zh: "两个分组，配等宽字体的组标题，中间用一根细线隔开。要用 SelectGroup 和 SelectLabel，别拿一个禁用项当标题：禁用项仍然是一个选项，所以读屏软件会把它数进去，报出一个比实际长一项的列表。这块面板从头到脚都是我们的，这正是重点——它不会在打开的那一刻就换掉字体、间距和选中色。选项超过十来个，这里就该变成 Combobox，因为一个没法过滤的列表，扫起来比一个能打字的更慢。" },
  "Select/02-invalid": { hash: '83879836', zh: "这套底子上唯一一个不读 aria-invalid 的控件。Field 的 error 会自己把 Input、Textarea 和 NativeSelect 画上，因为这三个两种拼法都认——Select 的触发器只看 invalid，所以一行只给了 error、别的什么都没给，最后就是一条红色消息底下配一圈静止状态的边框。两个都传。注意这里用的是 placeholder，而不是 defaultValue：一个打开时就已经答好的 select，是一个其实没人答过的 select。" },
  "Select/03-inside-a-form": { hash: '24116e47', zh: "name，以及它是干什么的。触发器是一个 button，而 Radix 只有在控件位于 form 里面时，才会渲染那个携带着值的隐藏原生 select——而且只有有名字的才发得出东西，所以一个没有 name 的 select 什么都不会提交，服务端看到的是一个没人填的字段。保存一下，下面那行会印出 FormData 实际收到的内容。" },
  "Slider/01-default": { hash: '32b51e29', zh: "一个值，然后两个，都开着读数。永远要传 defaultValue 或 value：那些滑块是从这个组件自己的数组渲染出来的，不是从 Radix 的默认值，所以一个两个都没给的 Slider，画出来是一条轨道，上面没有任何可拖的东西。一个双滑块的区间需要两个 name——第一个之后的每个滑块都会退回用第一个名字，否则价格筛选的两端都会把自己播报成 Minimum。数字上方那个标题只印第一个名字，所以要把它当成这一对的开头来读，而不是两个的标签。" },
  "Slider/02-with-an-input": { hash: '23effb1d', zh: "滑块负责大致区间，输入框负责那个数。滑块没法打字，所以一个要的是 1,150 而不是「大概 1,200」的人，得把一个 16px 的滑块横着拖过一百个刻度才到得了——只要精确数字才是重点，就在旁边放一个 Input。两者驱动同一份状态，所以谁都不会变馊，而输入的值在进来的路上会被夹住，因为一个超出最大值的数，轨道画不出来。" },
  "Slider/03-naming-the-unit": { hash: '2270bcc0', zh: "format 只管印，别的什么都不干：它渲染轨道上方那个读数，而这里没有任何东西设置 aria-valuetext，所以一个显示 12s 的滑块，播报出来是光秃秃的 12。单位属于名字，因为名字是会被播报的——「请求超时秒数」和 12 一起读出来是一个事实，而「超时」和 12 一起读出来是一个谜语。第二个滑块完全没有 format，一个普通计数就该长这样。" },
  "Switch/01-default": { hash: 'e873b9cc', zh: "两个一拨就生效、而不是等保存才生效的设置——这就是它和 Checkbox 之间那整条界线，而且不是装饰性的：一个开关放在带「保存」按钮的表单里，是在谎报这个改动是什么时候发生的。两个都是按状态命名的，不是按动作，因为名字会和「开」或「关」一起读出来：「邮件通知，开」是一句话，而「打开邮件通知，开」是两句互相矛盾的话。Radix 的根节点是一个 button，label 确实绑得上，所以不像 Select 或 RadioGroup，Switch 上方 Field 的那些字是真能点穿的。" },
  "Switch/02-a-failed-write": { hash: 'e87d7421', zh: "一拨过去就已经宣称改动发生了，所以一次失败的写入必须在控件这里收场：把滑块推回去，并说明为什么。把这个打开——它背后的请求过一会儿会失败，开关退回关，理由出现在它下面。一个停在「开」上、而写入从未落地的开关，是一个页面在展示一个服务端没有的设置。哪怕写入不是即时的，也要让那一拨保持即时：一个乐观的滑块配一次安静的撤销，好过在一个整个主张就是「它已经生效了」的控件上转圈。" },
  "Switch/03-a-third-state": { hash: 'b0891960', zh: "一个开关只有两个状态，没有第三个。「继承工作区的设置」在一条轨道上画不出来：它唯一可能的样子是未选中，而未选中会把自己播报成「关」——那是对另一个问题的另一个答案。左边是一个确实只有开和关的设置；右边是同一个设置在多出第三个取值之后的样子，那是一个 RadioGroup，不是一个被谁玩出花来的开关。" },
  "Textarea/01-default": { hash: 'dce79374', zh: "一个静止的、四行高的框。rows 是唯一能把它抬离六 rem 下限的东西，而这个框的高度，是一整页上关于「预期答案有多长」这件事最清楚的信号——所以把它设成你预期的那个长度。这里没有自动增高：高度永远不会跟着内容走，而一个留在默认值上的长答案，是透过一个六 rem 的窗口被审阅的。它只在竖直方向可调，因为一个横向的把手，会让读者把控件拖过版心、拖出页面的留白。" },
  "Textarea/02-rows-and-limits": { hash: '5991997f', zh: "rows 定框的大小，maxLength 给它封顶，而提示把这件事说出来。maxLength 单独用，会把按键悄悄吞掉、不作任何解释，还会把一次只多出一个字符的粘贴无声地截断，所以下面那个计数不是装饰——它是读者在这个框开始拒收之前，唯一能拿到的警告。这里 Enter 仍然是换行，也应该是：一个按 Enter 就提交的多行输入框，等于夺走了这个控件存在的意义所在的那一个键。" },
  "Textarea/03-invalid": { hash: '7b9c2d73', zh: "出错的样子，以及为什么那条消息要把规则重说一遍。hint 和 error 共用一个槽位，所以一个只写在提示里的格式，会在字段出错的那一瞬间消失——而那正是唯一有人需要它的时刻。Field 的 error 同时也就是整个 invalid 状态：它会在 textarea 上设 aria-invalid，而那正是那圈危险边框所读的拼法，所以没有什么需要传第二遍。" },
  "ToggleGroup/01-default": { hash: '9f566886', zh: "同一条分段控件的两种模式。single 带的是单选语义，会把一颗填充的药丸在选项之间挪来挪去，于是眼睛跟着一个移动的东西走；multiple 则各自填充每一段被按下的，因为这里没有一个「唯一选中项」可供移动。这个选择不是装饰——选错了，就等于在告诉读屏软件：选中一种格式会把其他的取消掉。一个 single 的组需要 defaultValue 或 value：那颗药丸只有在量到一个被选中的分段之后才会出现，所以一个空着开场的组，就是一条什么标记都没有的光秃秃的条。它既不换行也不滚动，所以最多到五段左右为止。" },
  "ToggleGroup/02-icon-only": { hash: 'db1f42b0', zh: "四个分段，只带图形、不带文字，用在文字只会把这一行已经说过的话再说一遍的工具栏里。这里没有 Button 那样的 iconOnly 路径——没有任何东西替你剥掉文字或补上一个名字——所以每一段都需要自己的 aria-label，而一条没有它们的分段控件，播报出来是四个没有名字的按钮。高度也要留神：分段是 --control-h-sm，宽松下 36px、紧凑下 30px，低于 44px 的指针下限，所以一条给拇指用的分段控件，得自己定一个高度。" },
  "ToggleGroup/03-never-switched-off": { hash: '32e51414', zh: "type=\"single\" 有单选的语义，却没有单选的行为：按下已选中的那一段会把它取消，并提交一个空字符串，所以拿它搭出来的视图切换器，可以被切到「没有任何视图」上去。做成受控的，防线就是一行——忽略那个空字符串，这条分段控件就保住它原有的值。按一下已选中的那一段，看着它待在原地。" },

  // ─── Display ───
  "Avatar/01-sizes": { hash: '9bbed574', zh: "三个固定的方块——28px、36px、48px——背后都没有图片，而一份真实列表里大多数行渲染出来就是这个样子。fallback 之所以必填，正是这个理由：它是那个永远都在的一半，图片才是可选的那个。这几个尺寸没有一个是控件，而且其中两个还低于一个控件所需的 44px 指针目标。" },
  "Avatar/02-a-name-beside-it": { hash: '926020ce', zh: "让头像变得可读的那种排布：名字就印在它旁边。这里的 alt 是刻意留空的，因为旁边的文字已经说清楚这是谁了——而且 alt 只有在 src 到位时才会进到 DOM 里，缩写字母又是 aria-hidden 的，所以一个没有照片的人，这个圆圈里根本没有任何无障碍文本，无论 alt 写得多用心。" },
  "Avatar/03-inside-the-control": { hash: 'b6953082', zh: "一个把头像装在里面的账户控件，而不是在圆圈上挂一个 onClick。根节点是一个没人让它可聚焦的 span，而 sm 是 28px，低于 44px 的指针下限——所以一个被接成菜单触发器的头像，同时既键盘够不着、又太小。按钮带来了目标区域、焦点环和无障碍名称；圆圈还是一张图。" },
  "Badge/01-tones": { hash: '66cf977a', zh: "徽标拥有的每一种 tone，中性的默认排在最前。除非这个徽标命名的是一个状态，否则就把它留在 neutral 上：那三个状态色是这套系统唯一花出去的彩度，而一个「因为页面想要红色所以是红色」的徽标，正是这套色阶存在要防住的东西。" },
  "Badge/02-with-a-status-dot": { hash: 'c8dfe249', zh: "圆点在这枚芯片里面，而不是旁边。Badge 会把它的子元素按 6px 拉开，所以 StatusDot 不需要自己再套一层——而且圆点是 aria-hidden 的，所以旁边那个词必须自己把状态说出来。用在行本身已经提供了主语的表格单元格里；一个状态如果就是一整行，那是 StatusPill。" },
  "Badge/03-on-a-stone-ground": { hash: '4e2f8b0f', zh: "同样两个词，放在其中一个会消失进去的底色上。neutral 拿 --stone 填充自己，边框画成透明，所以在一块 stone 面板上，它是一枚完全看不见边的芯片；outline 才是那个保住自己细线的 tone。只要徽标坐在一个有填充的表面上，就拿 outline。" },
  "Code/01-inline": { hash: '76ed808f', zh: "一个真的 <code> 元素，尺寸用 em，所以同一个 token 在正文里和在图注里都是成比例的。重点在这个元素，而不在那张等宽字体的脸：一个加了样式的 span 看起来一模一样，却对读屏软件什么都没说，于是被播报出来的是「pass 破折号 破折号 force」。" },
  "Code/02-a-literal-or-a-key": { hash: 'f2eebeb1', zh: "两枚读者肉眼分不出来的芯片，各用一句话说清。Code 是机器读、人照着敲出来的字面量；Kbd 是他们按下去的键。这个选择完全关乎含义，因为这两个元素被播报的方式不同——而一枚长得像按键的代码芯片，会招来一次没有任何东西回应的按压。" },
  "Code/03-a-list-of-flags": { hash: 'ecec35ec', zh: "同一枚芯片放进一份定义列表里，周围的字号更小。它按 0.85em 定尺寸而不是按像素，所以在术语列里、在正文里、在表格单元格里，都不用谁去挑一个尺寸就已经成比例——而且它不保留空白，所以交给它一个多行字符串，会被压成一整条。那种情况该用 CodeBlock。" },
  "CodeBlock/01-numbered-and-banded": { hash: 'ff1a9b47', zh: "朴素的那条路：不上高亮器，一个标题、一个语言标签、带行号，以及一行被标出来的行。行号住在它自己那一行的行内，而不是一条平行的边栏列里——两列共享一个 line-height，一直对得上，直到其中一列开始换行。复制按钮复制的是代码字符串，绝不是渲染出来的标记；那条工具条一直都在，而不是 hover 时才出现，而在触摸屏上 hover 出现就等于永不出现。" },
  "CodeBlock/02-a-command-to-copy": { hash: 'aacdd45b', zh: "最小的一块有用的代码块：一行、一个语言，加复制按钮。那条工具条不是 hover 出来的东西，从来都不是——一个 hover 时才出现的控件，在触摸屏上等于不存在，而触摸屏恰恰是读者最难用手去框选一条折行命令的地方。它复制的是代码字符串，所以渲染层面的任何东西都进不了剪贴板。用 label 而不是 title，因为这个块保持素面：这个名字是给那个滚动区域用的，不是给顶上那条工具条的。两个块并排放着，没有它就都退回叫「Code」，而两个共用一个名字的区域，是两个读者分不出彼此的地标。" },
  "CodeBlock/03-highlighted-somewhere-else": { hash: 'cfeabc8c', zh: "某个高亮器产出的标记，原样渲染出来。这个包不做高亮，也不会做：一份语法有几百 KB，而且那是构建期的活，所以本站在自己的生成器里跑 Shiki，再把结果交到这里。传了 html，lineNumbers 和 highlightLines 就会在类型层面被拿掉，而不是留成两个悄悄什么也不渲染的属性，因为 html 是一整条这个组件不会去解析的不透明字符串。code 仍然必填——它是复制按钮放进剪贴板的东西，也是读者真正带走的那一半。" },
  "CodeBlock/04-output-nobody-runs": { hash: '6c8cc2b7', zh: "一段日志，不是一条命令——copyable={false} 是给那种没人应该去运行的块用的，而这正是它存在的那个场景。别的地方按钮都要留着：为了让工具条清爽而把它去掉，等于拿走了读者不再用手去框选一条折行命令的那个理由。没有标题、没有语言、没有复制按钮，工具条里就没东西可放，于是也就没有工具条——而那个会滚动的正文仍然需要一个名字，label 就是干这个的。" },
  "Diagram/01-default": { hash: '569a8414', zh: "一次请求，画成三个层级，活儿嵌在中间那一层里面。只有被某条边点到名的节点才带 id，而每条边都是按数组的行进顺序写的：一条边是拿它紧挨着的前一个节点去匹配的，所以一条写成「到-从」的边，或者一条连接两个并不相邻的节点的边，什么都画不出来——但它会在开发环境里说出来，报 DIAGRAM_EDGE_NOT_ADJACENT；如果那个 id 根本不属于任何节点，报的就是 DIAGRAM_EDGE_UNKNOWN_NODE。另有三种 spec 写法会以同样的方式发出警告：DIAGRAM_DUPLICATE_ID；DIAGRAM_ACCENT_ON_CONTAINER，对应把 accent 加在一个带子节点的节点上，那个节点会被画成一条带子，根本没有可以上色的填充；以及 DIAGRAM_DIRECTION_ON_LEAF，对应把 direction 加在一个没有子节点的节点上。caption 既为读屏软件、也为读者命名这张图。" },
  "Diagram/02-containment-not-wiring": { hash: '1944a14c', zh: "只有结构、没有流向：不画边，只做嵌套。一个有子节点的节点会被画成一条带标签的细线带，没有子节点的则是一块板，正是这一点让一张三层深的图不至于在里面每样东西外面都套一圈边框。这同时也意味着 accent 只在板上上色——设在容器上它能编译、能过类型检查，然后什么都不显示，因为一条带没有可以承接颜色的填充。" },
  "Diagram/03-a-column-of-ranks": { hash: 'c806c682', zh: "同一套机器，侧过来一下。spec.direction 会把顶层那一排堆起来，箭头也跟着转向，而这也正是一排在 sm 断点以下自己会做的事——所以桌面上读起来像一条流水线的六块板，到手机上就是六个堆叠的盒子加五个箭头。子层级各守各的轴：direction 是从那个有子节点的节点上读的，从不继承上一层，这也是下面那三个存储仍然并排坐着的原因。" },
  "Diagram/04-the-node-it-is-about": { hash: '1a458058', zh: "一块带 accent 的板，这就是全部预算：accent 是这套系统唯一的填充，所以一张有三块的图，是一张什么都没在讲的图。footnote 印在盒子下面、盒子外面，留给那种一条注记装不下的句子。这份 spec 没有 caption，所以命名这张图那一组的是 label——两个都没有的话，读屏软件会播报出一个组，然后永远不说那是什么的组。" },
  "FigureBand/01-default": { hash: '1a5293dd', zh: "四个数字，它和二一样，是仅有的几个排得下的个数之一：容器到 @3xl 之前是两列、之后是四列，所以三个在两种排布下都留个洞，五个则留三个。id 是必填而不是可选，因为它就是 React 的 key——一旦列表重排，用下标当 key 会把下一次渲染的数字塞到上一个标签底下。" },
  "FigureBand/02-a-supporting-band": { hash: 'c636bd48', zh: "同一条数字带，降一档。scale=\"sub\" 是给那些为页面作支撑、而不是页面本身的数字用的——lead 是这条带做标题的那一档，所以一条支撑性的带设在那儿，是在跟它上面的标题抢同一级台阶。两个数字在任何宽度下都填满一行，这也是为什么值得去拿的个数是二和四。" },
  "FigureBand/03-a-note-is-a-second-value": { hash: '3da7d56f', zh: "什么该放进 note，什么不该。数值和注记是同一个 dt 底下的两个 dd，所以读屏软件会把它们当作同一个术语的两个值来读：「文章：48，另外今年 6 篇」成立，而一个解释原因的从句不成立。把它压在一个趋势、一个限定条件，或者第二个事实上——那种句子属于这条带周围的正文。" },
  "FigureBand/04-in-a-narrow-column": { hash: 'fec61659', zh: "同样这四个数字，放在一个 24rem 的列里，仍然是两个一排。这条带读的是容器查询，不是视口，所以它在判断的是这条带自己有多宽，而不是窗口有多宽——这也是为什么通过 className 往上写一个 sm:grid-cols-4，在一个 1440px 页面的侧栏里会是错的。把列拉宽，同样的标记自己就变成四个一排。" },
  "Heading/01-level-and-size": { hash: '4b3a3aa5', zh: "两个决定，分开做。level 是文档大纲——读屏软件靠它导航——而 size 是这一页的样子。默认会通过系统的那把梯子把两者绑在一起，而这把梯子在头两级之间跳了一档：--fs-lead 对 --fs-heading 的比是 1.14，读起来像个意外，而 --fs-title 对 --fs-heading 是 1.86，读起来才像一个层级。等宽的引题是这把梯子的第五档，这里由一个 h4 来穿，好让这一串在大纲里不跳级；最后一对是一个语义上正确、却不得不看起来像页面标题的 h3。" },
  "Heading/02-anchored-headings": { hash: '4c4bc671', zh: "两个目录能链进去的标题。每一个 Heading 都带着 scroll-margin-top: var(--scroll-offset)，所以给了 id 的那一个会停在顶栏下面，而不是被它盖住——页面上没有别的东西会这么做，这也是为什么一个链进手搓 h2 的锚点，落地时自己的标题正躲在那条栏后面。这个 id 属于调用方，而且必须稳定：每一个指向这一节的链接，说的都已经是它了。" },
  "Heading/03-a-fragment-that-starts-at-h2": { hash: 'd6c3d118', zh: "一块被放进一个已经有 h1 的页面里的面板。大纲决定 level——这里开的是一个 section，所以它是 h2，它的子标题是 h3——而 size 决定它看起来多大，这正是它们要做成两个属性的全部理由。为了够到更大的那一档而抬高 level，会让这一页有两个一级标题、以及一份没人能导航的大纲，换来的只是一个属性早就能给的差别。" },
  "Kbd/01-default": { hash: 'd2c15587', zh: "一个快捷键，就在解释它的那句话里面。两个键帽之间的空格是标记里真实的空格，不是组件画出来的东西，而每个键帽都是自己的 kbd 元素——正是这一点告诉读屏软件，这一串是按键而不是一个词。这里没有任何东西绑定了什么，所以只在真的有处理器在监听时，才把一个键印出来。" },
  "Kbd/02-one-cap-per-key": { hash: '421fc185', zh: "一组三键组合，画成三个键帽。一个装着 ⌘⇧P 的盒子是一个并不存在的按键，而那个让单个字符成方形的 min-w-[1.6em]，只会被撑开去装下这三个。那些符号键带着 aria-label，因为 ⌘ 和 ⇧ 会被念成它们的 Unicode 名字，或者干脆被跳过——一条只用符号写出来的 Mac 快捷键，是一条无声的指令。" },
  "Kbd/03-sized-by-its-copy": { hash: '28989cd0', zh: "同一个键，印在三档字号里。键帽是 0.8em，它的内边距也用 em，所以它的尺寸取自它旁边的一切——一个组件，在标题里、在正文里、在图注里都是对的。钉死成一个像素值，它就只在其中一处正确，而这正是同一个快捷键在同一页上长出三种尺寸的经过。" },
  "LinkArrow/01-default": { hash: '3721395d', zh: "这个记号，在锚点里面，并且是它的最后一个子节点。放到外面，它就是一个指向一条链接、而指针会差 0.22em 按不中的箭头。这个图形用 em 定尺寸，于是它跟着旁边的字走，而不是跟旁边的字较劲，而且它是 aria-hidden 的——把它放在这儿不会播报出任何东西，所以链接自己的那些词仍然必须说清楚它通向哪里。" },
  "LinkArrow/02-only-where-it-leaves": { hash: '47a03aec', zh: "三条链接，一个箭头。它标记的是目的地的改变，所以一份每行都带着它的索引，等于什么都没标，还为此每行付出 0.22em。那条外链在自己的文字里就写着「在新标签页打开」，因为箭头和 target=\"_blank\" 都不会被播报——没有那几个字，这个图形就是任何人能拿到的唯一警告，而且还得看得见才行。" },
  "LinkArrow/03-on-a-reversed-plate": { hash: '9bd00cdf', zh: "这个组件上唯一一处本来就打算被覆写的东西。它用的是 --ink-3-aa，那是对着纸色的 AA 下限，压在墨色上则几乎看不见，所以一个位于反色板上的调用处，会通过 className 把自己的颜色传进来。其余一切照旧：仍然是锚点的最后一个子节点，仍然是 0.68em，仍然 aria-hidden。" },
  "Markdown/01-a-string-into-nodes": { hash: '8fd1f630', zh: "一段不是这边的人写的字符串，渲染成这套系统自己的组件——整条路径上没有任何 dangerouslySetInnerHTML，所以既没有净化器要配置，也没有净化器会配错。headingLevelStart 是 2，因为这块内容坐在页面自己的标题底下，而那些标题拿到的 id 是从它们的文字 slug 出来的，好让目录能链进去。Article 是那根阅读列；Markdown 造的是坐在里面的那些节点，这也是它自己不渲染任何元素的原因。" },
  "Markdown/02-a-readme-fragment": { hash: '504b66fa', zh: "一份 README，直接从仓库里拿出来，渲染成这套系统自己的组件。嵌套列表、有序列表、带语言的围栏、行内代码和链接，全都出自内置的解析器，而且一样都没走 dangerouslySetInnerHTML——那些节点是 React 元素，所以既没有净化器要配置，也没有净化器会配错。headingLevelStart 是 2，因为不这样的话，文档自己那个 # 会成为这一页上的第二个 h1。" },
  "Markdown/03-an-answer-mid-stream": { hash: '5343362c', zh: "一段模型的回答，被 token 上限从围栏中间切断了——它渲染出来是一个代码块，而不是一个异常，因为一个没闭合的围栏会一直延伸到文档末尾，CommonMark 说的正是这样。这里没有任何东西是一份文档，所以没有 Article：这段片段直接进到会话本来就有的那个盒子里，间距也由那个盒子提供，因为 Markdown 自己不渲染任何元素，而它造出来的每个段落都是 margin: 0。" },
  "Markdown/04-shifting-the-outline": { hash: '9285557d', zh: "同一份文档，放在一个已经存在的标题底下。headingLevelStart 是它所在那一级的下一级，所以这份指南的 # 渲染成 h3，里面的每一级一起往下挪——不挪就丢进去，它会成为第二个一级标题，以及一份读屏软件没法导航的大纲。idPrefix 给生成的 id 加上命名空间，好让一页上的两份文档不会都来认领 #installing，而 slugify 被导出来正是为了这个：目录不用回头去 DOM 里读，就能得到同样那些 id。" },
  "Markdown/05-your-own-parser": { hash: '9f243311', zh: "任务列表不在内置语法里，所以一个带方括号的 x 就是一段字面文本，别的什么都不会发生——是安静，不是坏掉，这里每一个不支持的特性都是这个形状。parse 就是那道接缝：任何一个从字符串到 MarkdownNode 的函数，所以它能接下一整条流水线（markdown-it、remark、一份你手上已经有的 AST），或者像这里一样，只把语法不认识的那一样东西重写掉，剩下的仍旧交给随包附带的解析器。" },
  "Separator/01-weights": { hash: '51267193', zh: "三档粗细，按它们该被花出去的顺序排开。它们是有次序的、不能互换，所以两行表格之间一道 hard 的线，是在告诉读者这张表到那里就结束了——而 hard 那一档不是更深一点的灰，它就是 --ink 本身。三档有名字的粗细就是全部；第四种靠肉眼在 className 里调出来的灰，正是一张单色页面开始走样的方式。" },
  "Separator/02-vertical-needs-a-height": { hash: 'c0e1816f', zh: "一行元信息，被竖直的线分开。竖直那种形态是 h-full，而对着一个自己没有高度的父元素，它解析出来是零——元素渲染了、不占任何空间，读起来像一个没加载出来的组件。给它一个高度，就像这里，或者给一个会把子元素拉满的行。" },
  "Separator/03-announced-between-sections": { hash: 'dd1374d1', zh: "那种真的在干活的线。decorative={false} 会把 role=\"none\" 换成 role=\"separator\"，并连带设上 aria-orientation，于是读屏软件听到的是两个彼此分开的区块。只在这条线是分开它们的唯一东西时才拿它——一个把每行之间的细线都播报出来的页面，读出来是一串分隔符。" },
  "Separator/04-words-in-the-rule": { hash: 'e3a08e73', zh: "断口里的字。label 改的是构造方式，而不是样式：这条线被画了两遍，字的两侧各一段，中间那道缝就是一道真的缝——所以它落在任何底色上都是对的，而且不需要谁告诉它自己落在哪一种上。常见的单元素做法是把文字盖在一条完整的线上，再用一个背景色在线上打个洞，而在一张 --stone 的卡片上，那个洞是 --paper，读起来像一个渲染 bug。只有水平方向，而且 decorative 不再适用，因为那些字是内容。" },
  "StatusDot/01-tones": { hash: '4fda53a6', zh: "四种 tone，每一种旁边都配着那个命名它的词。这个点无一例外都是 aria-hidden 的，所以 tone 是这个组件里辅助技术永远看不见的那一部分，状态只能由标签自己扛——在点上加 aria-label 什么也换不来，因为一个被隐藏的元素没有名字可给。只有正在进行中的那个会脉动；一切已经落定的都把 pulse 设成 false。" },
  "StatusDot/02-live-and-settled": { hash: '710cb887', zh: "同一种 tone，两遍：脉动的意思是此刻正在发生什么，而且它是默认值——所以一个表示构建已完成、或者今天不会再变的状态的点，是在播报一份并没有在做的工作，除非把 pulse 设成 false。那圈光晕是 motion-safe 的，所以一个要求减少动效的读者，两边拿到的都是静止的点。" },
  "StatusDot/03-down-a-table": { hash: '9b0317fc', zh: "一列状态，用的是这个点该有的尺寸。sm 是 7px，对着 md 的 8px——那是为了坐在更小的字旁边而做的视觉微调，不是一套尺寸阶梯，所以布局里不该有任何东西建立在这个差值上。这个点直接坐在它标签旁边那个 flex 行里：shrink-0 才是让它保持圆形的东西，而一个被裹进可收缩盒子里的点，只要标签一长就会变成椭圆。" },
  "StatusPill/01-default": { hash: 'e0177a25', zh: "整枚药丸，而不是在调用处拿一个点和一个 span 拼起来，后者正是同一枚「接受委托中」的芯片在同一个站点上长出三种点尺寸、两种脉动节奏的经过。tone 只够得着那个点，而点是 aria-hidden 的，所以那些字必须自己把状态说出来：「部分故障」放在一枚 warning 药丸里和放在一枚 neutral 药丸里，对任何看不见颜色的人来说是同一句话。" },
  "StatusPill/02-settled-and-live": { hash: 'e5b1d4ee', zh: "每一种 tone，而脉动只花在那个真正正在发生的状态上。光晕的意思是「此刻」，所以一枚已归档或已发布的药丸还留着脉动，是在告诉读者有什么是活的，而其实什么都没有。这枚药丸还只是一个普通的 span，不是一个实时区域：一个在读者停留期间从 Live 翻到 Degraded 的状态，除非调用处把它包进 role=\"status\"，否则是悄悄变过去的。" },
  "StatusPill/03-one-per-view": { hash: 'df65b406', zh: "一个视图配一枚药丸，它底下那些行配徽标。这个标签是一行 0.12em 字距的大写引题——这套系统里最响的小字号——所以一列药丸顺着列表排下去，就是每一行都在用同样的方式喊。Badge 用朴素的 12px 等宽字承载同样那几种状态色，而那才是一条记录级的状态该有的样子。" },
  "Steps/01-default": { hash: '836a5d80', zh: "一条流水线画成一根轨：一件接着一件，每件用一个名词做名字，底下一行等宽字写细节。顺序就是内容，所以这是一个 ol——而 label 是这份列表在这里唯一的名字，因为它上面没有任何标题说明这串序列是什么。恰好有一个步骤是当前的，而这正是这根轨用陈述而非绘制来表达的那一件事。" },
  "Steps/02-states-not-instructions": { hash: '19e01e09', zh: "同一根轨，去掉数字。marker=\"rule\" 是给一串状态用的——排队中、构建中、已发布，是这个流程经过的一个次序，而在每一个前面摆一个数字，是在告诉读者它们是要去执行的步骤。填充的标记说明它走到哪儿了；出现第二个 current，会把这次发布同时放在两个地方。" },
  "Steps/03-notes-that-carry-code": { hash: '056ea6d3', zh: "note 收的是节点、不只是字符串，所以一个步骤可以直接带上那条确切的命令，而不是对它的一段描述。无论哪种，都压在短短一行以内：这根轨是一串序列，而标记底下的一整段，会把它打回它本来要取代的那种编号列表。这里没有任何东西可点——那些属性是摊到 ol 上的，所以一个本意给某个步骤的 onClick，会落在整份列表上。" },
  "Tag/01-default": { hash: '6ece8bda', zh: "一行分面，其中一个被选中了。accent 的填充是这套系统唯一那个指向「所选」的手段，所以一行需要一个可以退回去的关闭态——每个标签都激活，等于把那个意思是「就是这个」的记号花在了全部身上。这里没有任何东西可点：没有 onRemove 时，Tag 就是一个普通的 span，而按钮、焦点环，以及那个让选中状态可被听见的 aria-pressed，都属于调用处，下一个例子会展示。" },
  "Tag/02-a-filter-row": { hash: '851bdb20', zh: "同一行，做筛选。按钮在标签外面：那个 span 自己带着 10px 的内边距，所以嵌在它里面的按钮，是一个只有文字那么大的目标，外面围着一圈死掉的、却看起来仍然可点的边距。aria-pressed 要和 active 同一口气设上，因为 active 只负责上 accent 那个色，此外再没有别的途径够到辅助技术——没有它，被选中的那个分面就成了一个只有看得见的读者才能看见的状态。" },
  "Tag/03-tag-badge-or-pill": { hash: '5438ce18', zh: "三枚长得几乎一模一样的芯片，摆在同一条记录上，各自都有它是正确答案的那一处。Tag 命名的是这条记录关于什么，所以好几个会一起坐着、供人扫读；Badge 是关于某一条记录的一个事实，这也是为什么它承载状态色而标签一个都不承载；StatusPill 是视图自身的实时状态，最多一枚，用的是这套系统里最响的小字号。当你会想在它旁边再放一个的时候，就拿标签。" },
  "Tag/04-a-removable-chip": { hash: 'bec74056', zh: "可移除的那种形态：给读者已经选好的东西用的芯片。这里本来是一个独立的 Token 组件会去的位置，而两者的差别是一个属性，不是一个组件。removeLabel 必须和 onRemove 一起给，而不是默认成「移除」，因为八个都叫「移除」的控件，是八个读屏软件分不出彼此的控件——把主语写进去。" },
  "Text/01-sizes-and-tones": { hash: '02e3f0da', zh: "四档字号，对着三级墨色。默认是 base 配 body，而后者刻意是 --ink-2 而不是 --ink：一张段落全是满强度墨色的页面，等于把这把梯子的顶端花在了正文上，给标题就什么都不剩了。每一个 Text 都是 margin: 0，所以这几段之间的间距来自容器，而不是段落。" },
  "Text/02-a-run-inside-a-sentence": { hash: '9e488e8d', zh: "as 只换元素，别的什么都不换。放进一句话里，它必须是 span：p 套 p 不是嵌套——HTML 解析器会把外面那个关掉，留给你两个段落和一个坏掉的布局。放进别人开好的列表里，它就是 li，于是标记说明内容是什么，而字型停在 size 和 tone 放它的地方，一动不动。" },
  "Text/03-a-standfirst-under-a-title": { hash: 'a4fb0ff1', zh: "lead 唯一该待的地方：一篇文章的导语，就在它标题的正下方。它是 --fs-item，标题梯子最下面那一档，而这把梯子也就到此为止——一个比记录标题还大的段落，是一个没有承认自己是标题的标题，而那个尺寸的 p，对读屏软件用来导航的标题列表来说是隐形的。这里的间距来自那一列，因为每一个 Text 都是 margin: 0。" },
  "Timestamp/01-relative-and-absolute": { hash: '5a70903b', zh: "同一个时刻，三种写法。这里每一页都是静态导出的，所以第一次绘制——构建产出、浏览器在水合时必须一模一样复现的那一次——是 UTC 的日历日期，直接从 ISO 字符串里切出来，完全不经过 Intl。相对形式和跟着地区走的形式是挂载之后才应用的，那时候才有一个读者可以「跟着他所在的地方」。datetime 属性从第一次渲染起就是完整的 ISO 时刻，此后永不改变。" },
  "Timestamp/02-a-column-of-records": { hash: '5700a49c', zh: "真实的用法，也是这个组件之所以存在、而不是在每个调用处写一句 toLocaleString 的理由。这一列里干活的是 auto：靠近现在的那些行读起来是一段相对的间隔，更早的则是日历日期，切换点在一周，因为过了这个点，日期既是更有用的那个事实，也是那个不再变化的事实。它每次挂载只格式化一次——一百行各自握着一个定时器，只为了让「三小时前」保持诚实，是一笔没人要求过的开销，所以一份必须走秒的列表，应该从上面重新渲染。" },
  "Timestamp/03-what-the-markup-carries": { hash: '87707e92', zh: "同一个时刻三遍，旁边就是它们全都由之构建出来的那个字符串。这一页是静态导出的，所以第一次绘制——构建产出、浏览器在水合时必须一模一样复现的那一次——是直接从那个字符串里切出来的 UTC 日历日期，Intl 一点边都没沾：两边是从同样的字符算出来的，所以它们不可能不一致。跟着地区走的形式和相对形式是挂载之后才应用的，那时候才有一个读者可以「跟着他所在的地方」。datetime 属性从第一次渲染起就是那个完整时刻，此后永不改变，而无论那个 effect 有没有跑过，读屏软件或者爬虫读到的都是它。" },

  // ─── Feedback ───
  "Alert/01-tones": { hash: 'b5328d6d', zh: "四种 tone，按它们升级的顺序排开。tone 是这条消息的严重程度，不是它的装饰：danger 带的是 role alert，会打断读屏软件正在念的任何内容，因为读者手上的事已经在失败了，而另外三种带的是 role status，会等一个停顿。颜色被图标和文字各重复了一遍，所以含义在单色打印和色觉障碍下都还活着——而这正是 hideIcon 拿走的东西，只把严重程度留在一层 13% 到 16% 透明度的淡色上。不要把它们当成一份滚动日志堆起来：一页五条，就是五个实时区域在抢同一条语音队列，而其中那条 danger 会把解释它的另外四条切掉。" },
  "Alert/02-a-failed-submit": { hash: '7962e244', zh: "一个必须留在页面上的错误，出路就在它里面。把重试放进 action，而不是在正文里描述它：action 坐在实时区域内部，而这正是「播报告诉读者该做什么」和「只告诉他们出了点事」之间的差别。有话要说时把 Alert 挂上，没话说时把它卸掉——一个长期留在页面里的区域，只有在它的文字变化时才会播报，所以第二次提交失败、消息还是同一条的话，播报给了空气。把焦点移到它上面，或者移到它点名的那个字段：它播报完就待着不动，所以用键盘的读者是站在原地听到这条错误的。" },
  "Alert/03-inside-the-panel": { hash: '39764297', zh: "一块面板失败了；页面其余部分还能用。这正是一个全屏 ErrorState 会搞错的场景——把整个视图换掉，等于把读者用来脱身所需要的导航一并丢掉，而面板里的一条 Alert，既留住了错误、也留住了绕过它的路。只有当页面本身就无法显示时，才拿页面尺寸的那种状态。这里的 tone 是 warning 而不是 danger，理由相同：读者做的事没有失败，而 danger 强势到足以打断他们正在页面别处读的东西。" },
  "EmptyState/01-default": { hash: '25586fe5', zh: "一个刚建好的集合，以及接下来要做的那一件事。文案说的是该做什么，而不是什么失败了，这就是它和 ErrorState 之间的全部差别，也是它们是两个组件、而不是一个组件加一个 variant 的理由。这个框不带 role、也不带实时区域，所以把一个 SkeletonPage 换成它，等于把那个说着「正在加载项目」的区域移走、又没放任何东西进去——到达这件事得你自己去播报。title 会开一个二级标题，紧跟在页面的 h1 下面时这是对的；放在一个已经有自己 h2 的区块里，就传 level={3}，别在标题导航里留个洞。" },
  "EmptyState/02-emptied-by-a-filter": { hash: '807dab93', zh: "同一个组件，说明这是哪一种空。在一个正生效的筛选器上方显示「还没有项目」，是在告诉读者他的项目没了，而从这个念头里恢复过来的代价，比那句话本身要大得多——所以把开着的筛选条件点出来，说明清掉它们能换回什么，并且让那个动作成为脱离此状态的出口，而不是第二个入口。description 被限制在 24rem 并居中，好让它保持是一句话：更长的文案会变成一根又窄又参差的柱子，眼睛还没读到要紧的那一段就折回去了。" },
  "EmptyState/03-empty-or-failed": { hash: 'e47d11cc', zh: "「这里还什么都没有」对上「出错了」。这一对并不对称，这正是这个区分要紧的原因：一个被告知请求失败的读者会去重试，而一个被告知集合是空的读者会去行动——去创建一条他手上其实已经有的记录，或者去上报一次根本没发生的数据丢失。所以请求出错时就说出来，哪怕这一天那份列表本来也会是空的。真实使用中两者都是视图尺寸的——错误那一侧是整屏视口，空那一侧带着 160px 的上下留白；这里各自缩短了，好共用一块画布。" },
  "ErrorState/01-not-found": { hash: 'f8d89ed1', zh: "那个显示不出来的页面。要用它代替这个页面来渲染，而不是渲染在页面里面：它是一整屏视口，自带底色和顶部净空，所以嵌进一个已经有页头的布局里，会在首屏以下再加一屏空白——这里的例子传了 min-h-0 来适配画布，也传了 level={2}，因为本页自己的 h1 就在它们上面。code 位于字号梯子的顶端，而且是 aria-hidden 的，所以紧随其后的标题必须用文字把同一件事再说一遍。这里也没有实时区域，所以一个把整屏换成它的路由，改掉了看得见的读者能看见的一切，却什么都没说。" },
  "ErrorState/02-a-way-back": { hash: 'cb789123', zh: "action 是必填而不是可选，因为它是这一屏上唯一可聚焦的东西——而且它必须指向一个真实的目的地，而不是指向历史记录。一个读者从冷启动、或者从别人给的链接到达一个错误页的次数，至少和从应用内部到达一样多，所以「返回」会把他送回刚刚失败的那个页面，或者送到什么都没有的地方。两条链接差不多就是它该承载的上限：回家的路，以及那个能说明「是不是只有我这样」的页面。" },
  "ErrorState/03-the-trace-id": { hash: 'fbb45e01', zh: "那串编号该去哪里：写进消息里，绝不写进 code。code 是按 --fs-title 配 leading-none 排的，而且是 aria-hidden 的，所以一个放在那儿的 request id 会成为整页上最大的物体，同时又对那个最可能要在电话里念出它的读者完全隐形。那个槽位的尺寸是照着三个字符定的；编号属于句子里，在那儿它可被选中、可被复制，也会和其余的解释一起被念出来。" },
  "Progress/01-determinate": { hash: 'ae1ad385', zh: "一条带着真实分数的进度条，名字就在屏幕上。showValue 是唯一会把 label 印出来的东西：没有它，那个名字只以 aria-label 的形式存在，而看得见的读者面对的是一条 4px 的、没有标签的线，连数字都没有。value 是一个百分比，别的什么都不是——这个组件会静悄悄地把它夹在 0 和 100 之间，所以一个被低估了的总量，会让进度条在剩下的整个过程里停在 100%，而不是承认那个估计错了。className 修饰的是那一列、不是轨道，所以往那儿传一个高度工具类，会把外层容器撑高，而那条 4px 的进度条原地不动。" },
  "Progress/02-indeterminate": { hash: 'a687ad96', zh: "没有 value，于是进度条来回扫而不是填充，aria-valuenow 也会被丢掉——读屏软件被告知的是「不确定」，而不是一个猜出来的数字。那一行数值只有在 value 是数字时才渲染，所以来回扫的进度条什么都不会印出来，名字必须用别的方式出现在页面上，就像这里。别让这样一条永远挂着：在 prefers-reduced-motion 下，那次扫动会停成一条 40% 不透明度的满宽横条，而那正是一条已经走完的进度条的样子，于是一个要求减少动效的读者，看到的是一个在说「已经完成」的东西。" },
  "Progress/03-bytes-into-percent": { hash: '73e1bbb0', zh: "数量属于调用方，百分比属于进度条。在调用处相除，并且取整——印出来的数字是取过整的，但 aria-valuenow 是你传进来的那个数，所以一次没取整的除法会播报出十五位小数——再把真实的数字留在下面那一行，让读者能读到。没有任何办法把一个总量交给这个组件：无论旁边还传了什么，value 都会被夹到 100，所以一条被告知总量是 500 的进度条，会把自己画满，并播报「五百分之一百」，而按读屏软件唯一能读到的东西算，那是百分之二十。估计一旦不再真实，立刻把 value 切回 null：填充部分的宽度是带过渡的，所以一个往回修正的数字会倒着动画，读者会眼看着进度自己撤回去。" },
  "Sidebar/01-default": { hash: '0e411d23', zh: "这条栏是组合出来的，不是配置出来的：一个头部、一个会滚动的中段、一个底部，而每个产品在这三处想放的东西都不一样。组件持有的是各处都相同的那一半——宽度、边线、滚动，以及它关起来时会发生什么。按一下头部里那个按钮，或者 Cmd+B，看着文字消失：那些行仍然够得着，因为每一行都把自己的文字留在了 tooltip 里，而不是变成一个没有名字的图形。" },
  "Sidebar/02-offcanvas": { hash: '53e78bd3', zh: "collapsible 是关于那些行的选择，不是关于动画的。图标适合读者会记住形状的一组固定项——一个工作区、一个邮件客户端、他们每天要去的五个地方。而一份没人会背下来的长目录，还不如整条收走：一列认不出来的图形既占宽度又什么都不回答，offcanvas 就是为这个准备的。无论哪种，开关按钮都留在头部，所以它跟着这条栏走，而不是丢在顶栏里、和它操作的那一列毫无关系。" },
  "Skeleton/01-record-list": { hash: '4b7e0f42', zh: "那份列表的骨架，和取代它的东西建立在同一套栅格上——一块 9rem 的板，旁边是引题、标题和两行正文。这份吻合就是全部的活儿：一个形状和最终落下来的东西不一样的骨架，是一次读者事先被预告过、然后照样挨了一下的布局位移。一个 SkeletonPage 把整批包住，于是只有一个实时区域、一句被念出来的话，和一次脉动，而不是八条各自岔开呼吸的横条。这里没有任何东西把 aria-busy 翻成 false——这个框是被卸载的，不是被更新的——所以取代它的东西必须自己播报，或者接管焦点。" },
  "Skeleton/02-parts": { hash: 'afd93d19', zh: "四个预设，配同一种填充。Skeleton 自己只设一层 --stone 底色，别的什么都不设——没有高度、没有宽度、没有圆角——所以一个光秃秃的它渲染出来是一个零高度的 div，什么都看不见；每一个尺寸都来自 className。SkeletonCircle 固定 36px，SkeletonLine 固定 12px 高，无论它们代替的是什么，这也是为什么一份在不同屏幕之间复制过来的骨架，必须对着它现在所代替的东西重新量一遍。别给某个部件再加 animate-pulse：那个框已经在做透明度动画了，子元素上的第二条曲线会和它相乘。" },
  "Skeleton/03-shape-match": { hash: '8d060f25', zh: "同一条评论两遍：占住位置的那个形状，以及落进这个位置里的东西。SkeletonCircle 是 36px，而默认尺寸的 Avatar 也是 36px；那条名字线的高度，就是取代它的那行说明文字的高度；两条正文横条结束的地方，正是真正的句子结束的地方——所以换过来的那一刻，页面上没有任何东西动。一份没有对着任何东西量过的骨架，是一次多绕了几步的布局位移：它承诺了一种布局，然后页面从那个已经在读它的读者脚下跳开。" },
  "Spinner/01-sizes": { hash: 'b0bf628e', zh: "三个圆环——14px、18px、26px——是对着它们旁边的字号配的，不是为了强调挑出来的。size 是唯一能改它大小的东西：className 落在外层容器上，所以那样传一个尺寸工具类，只会在一个没变过的圆环外面撑出一个空盒子。label 默认是光秃秃的一个「Loading」，而那恰恰是这个属性存在要防住的播报——把具体在等什么写出来，因为三个都说着「Loading」的转圈，对读屏软件而言什么都没说，而且每一个只在挂载时被读一次，此后再不会读。" },
  "Spinner/02-on-a-filled-ground": { hash: '2586f082', zh: "两个转圈，站在一块不是纸色的底上。默认的 tone 会在一条 --rule-2 的轨道上，用 --ink 画出领头那四分之一，而在一个有填充的控件里，这两个颜色都正是它所站的那块底——所以传 tone current，让圆环去继承文字颜色。label 传 null 恰恰属于这个场景：控件本身已经把这个操作命名了，而传它会把整个元素对辅助技术隐藏起来，不只是把文字去掉，所以一个被消了音、又独自站着的转圈，是一次没人被告知的等待。" },
  "Spinner/03-which-wait-shape": { hash: '9a6f4d43', zh: "三种等待、三种形状，以及每一种回答的问题。Spinner 是给那种没人知道要多久、结果也没有值得预告的形状的等待用的。Skeleton 是给形状已知的等待用的——它把布局占住，好让记录落下来时页面不跳。Progress 是给有真实分数的等待用的，而且只给真实的那种：一条按编出来的估计填的进度条，是一个会撒谎的转圈。三种情况一律拿转圈，是常见的失败，而它恰恰是三者里说得最少的那一个。" },
  "Toast/01-default": { hash: '1da80e60', zh: "三种类型，以及它们共同抵达的那一个 Toaster。恰好挂一个，挂在应用根部附近：每一次 toast 调用都会抵达每一个在听的 Toaster，所以嵌套布局里多挂的第二个，会把同一条消息渲染两遍，在两个角落里。这个区域对每一种类型都是 aria-live polite——这里没有 assertive 那条路——所以一个用 toast.error 报出来的失败，会排在读屏软件已经在念的东西后面，而且可能还没轮到它，就被计时器移走了。失败也要在页面里报一遍。" },
  "Toast/02-long-enough-to-read": { hash: 'df6348f2', zh: "默认是四秒，而四秒大约是念出十个词的时间：任何比一个短句更长的东西，都需要一个自己的 duration，否则剩下那部分还没被读到，就已经从页面上撤走了。消息也要压在「发生了什么」上——同时只看得见三条，其余的排队，所以一个每处理一项就 toast 一次的循环，展示的是最后三条，而其余的会在读者已经走开之后才送到。这个例子里刻意没有 Toaster：本页第一个例子挂的那一个，就是这一页该有的唯一一个。" },
  "Toast/03-not-in-a-toast": { hash: '8fb36a65', zh: "同一个失败两遍：一遍在页面里，一遍挂在计时器上。任何读者必须去处理的东西，都不属于那个会消失的版本——四秒是一个从没告知过他们的期限，而那个关闭按钮住在 body 末尾的一个 portal 里，键盘最后才够得到。任何他们必须读第二遍的东西也不属于那儿：这里没有历史记录，所以计时器一到，那串编号就出了 DOM，再也找不回来。按一下按钮，看着那个数字走掉；上面那条 Alert 还在，而且还在说该做什么。" },

  // ─── Overlays ───
  "Command/01-inline": { hash: '4dc27c98', zh: "命令面板的各个部件，摊平在行内，好让它们同时可见：那个 combobox 输入框、带分组和分隔线的过滤列表，以及印着按键的页脚。在应用里要拿 CommandDialog，而不是这个光秃秃的根——这个根是一个行内的带边框盒子，没有遮罩、没有焦点陷阱、自己也不处理 Escape，所以拿它搭出来的面板会一直开着，直到别的什么东西把它关掉。永远渲染 CommandEmpty：cmdk 只有在树里存在一个空状态时才会显示它，所以一个没有它的面板，对一次匹配不上的过滤，回应的是一条空白的带子。另外注意，这里的 icon 属性收的是一个元素，和一个 import 之外的 DropdownMenuItem 正好相反。" },
  "Command/02-dialog": { hash: '65ed605f', zh: "命令面板几乎总是被使用的那个样子：模态、偏上居中，由这个例子自己绑定的一个按键打开。组件里没有任何东西在监听按键——只有应用加上处理器之后，这个快捷键才存在——而 CommandDialog 是带着 hideTitle 和 showClose={false} 渲染的，所以既没有可见的标题，也没有可见的关闭。Escape 和遮罩是仅有的两个出口，而且两个都不会自报家门，这也是为什么这里把快捷键印在页面上，以及为什么一个真实的面板会带一个 CommandFooter。这个处理器在 defaultPrevented 时会退出，好让它不跟另一个已经绑了同样按键的面板打架。" },
  "Command/03-values-and-keywords": { hash: 'bad6869e', zh: "cmdk 是按条目的 value 过滤的，只有在没有 value 时才退回用这一行自己的文字——所以把一个内部 id 当成 value 传进去，会让看得见的标签搜不出来，而这正是一个面板带着毛病交付出去最常见的方式。这里每一个 value 都是读者真的会去敲的东西，而每一行的后半段是一份 keywords，装着他们可能改敲的那些词：回滚配 revert，找人配 teammate。meta 是行尾那条安静的注记，说明这是哪一类东西——不是描述，因为一个每行都印一句话的面板，大约到第六行就不再能扫读了。" },
  "ContextMenu/01-on-a-region": { hash: '208a759d', zh: "一次右键打开的菜单，位置定在指针处，而不是贴着触发器——这里没有 side 或 align 可设，只有那点把它留在框内的碰撞留白。永远不要让它成为够到某个动作的唯一途径：在平台支持的地方，Shift+F10 可以从键盘打开它，而 Radix 对触摸和触控笔会在长按 700ms 时打开、指针一动就取消，所以在一个可滚动的列表上，通常是滚动手势赢。那个分组标签是一个不带 role 的普通 div，和 DropdownMenu 的一样——一个视觉上的小标题，读屏软件一行行走过去时听不到它。" },
  "ContextMenu/02-two-doors": { hash: 'b8f9f7f1', zh: "一个动作数组，两扇进去的门。ContextMenuItem 和 DropdownMenuItem 收的 icon、destructive 和 disabled 属性完全一致，所以同一份列表可以同时喂给两边，于是右键成了快捷方式、而不是唯一的入口——这很要紧，因为一个触摸用户、一个触控板用户和一个键盘用户，可能根本没有办法打开一个右键菜单。列表只写一次：两份靠手维护的副本，正是那个溢出按钮最后漏掉某人加进右键里的动作的经过。" },
  "ContextMenu/03-a-card-trigger": { hash: 'e321cbab', zh: "asChild 把 Card 本身交给了 Radix。没有它，Radix 会在触发器和子元素之间插一个 span，而那个 span 会成为网格项，卡片则作为行内内容排在它里面——一个看起来坏掉了、而页面上没有任何东西指向原因的布局。这个菜单是模态的，所以打开期间背后的页面被锁住滚动、也不接受指针：对着一个对象的一小串动作，它是对的；对着任何需要读者滚动页面才能回答的东西，它是错的。" },
  "Dialog/01-a-destructive-confirm": { hash: '09eceb27', zh: "一个问题、两个答案，面板里再没有别的。两个控件都包在 DialogClose 里，而不是自己手动翻状态：这样关闭走的是 Radix，它会把焦点交还给触发器，而不是把焦点丢在文档顶上。title 是给这个模态命名的东西——不写它，兜底的无障碍名称就是字面的「Dialog」，于是一个应用里每一个没命名的模态，播报出来都是同一个东西。答案是「是」或「否」时拿这个形状；任何更长的东西，都已经变成一个 Sheet 了。" },
  "Dialog/02-a-hidden-title": { hash: '326bb515', zh: "一块自己画页头的面板——标题上方一个引题，旁边一枚徽标——这是那行朴素的标题表达不了的。hideTitle 阻止那一行渲染两遍，而 title 仍然为读屏软件命名这个对话框，所以即便在这里也要传它：完全不给 title，无障碍名称就退回字面的「Dialog」。hideTitle 会把 description 一并带走，因为两者共用一层容器，所以任何读者必须读到的东西都放进 children。showClose 保持开着，就像它的默认值一样：除此之外只有 Escape 和遮罩两条出路，而它们都是看不见的。" },
  "Dialog/03-or-a-sheet": { hash: '53abff55', zh: "同一个模态的两种长度。Dialog 到 32rem × 85vh 就打住，超出的部分在自己的正文里滚动，这对一个问题是对的，对一份表单是错的：读者失去了页面边缘这个锚，还得在一个盒子里滚另一个盒子。Sheet 是同一个组件停靠到边上——同样的遮罩、同样的焦点陷阱、同样的滚动锁定——但有整个视口的高度可花。所以这个选择只关乎内容需要多大地方，别的什么都不关乎。两者都通过 DialogClose 或 SheetClose 关闭，好让焦点回到触发器上。" },
  "DropdownMenu/01-an-account-menu": { hash: 'fbd29af5', zh: "一个动作菜单，而它也只该是这个：会导航的行属于 nav，会设定某个值的行是 Select 或 RadioGroup。有两处细节容易搞错。icon 收的是 Lucide 组件本身——icon={Settings}，绝不是 icon={<Settings />}——而这和一个 import 之外的 CommandItem 恰好相反。还有，触发器需要 asChild 配一个真的 Button，否则 Radix 会渲染一个自己的、没有样式的 button，于是菜单挂在了一个不属于这套系统的控件上。那个分组标签是一个不带 role 的普通 div：它为眼睛把几行归拢在一起，而一个按 role 走菜单的读屏软件永远不会听到它。" },
  "DropdownMenu/02-an-overflow-button": { hash: '1db29c03', zh: "行尾那个溢出控件，用在文字只会把这一行已经说过的话再说一遍的地方。触发器是一个 iconOnly 的 Button，所以 aria-label 不是可选项——没有它，这个控件会被播报成一个没有名字的按钮。align 用 end，因为面板至少 11rem 宽，否则会朝回展开、盖住它自己的触发器；它以 8px 的留白与外框碰撞，然后翻边而不是滚动，因为这个面板没有最大高度。此刻不可用的行要做成 disabled，而不是干脆不放，好让这份列表不会在两次访问之间改变形状。" },
  "DropdownMenu/03-where-it-opens": { hash: '7d49bca9', zh: "工具栏两端各一个菜单，各自对齐它所在的那一边。align 决定面板和触发器的哪一侧对齐，而面板至少 11rem 宽——所以一个位于末端、却留在默认 center 上的菜单，会朝回展开盖住自己的触发器，然后被那 8px 的碰撞留白推开。下面没地方时，side 会把整个面板翻到上面去，而一个很长的菜单也是同样的下场：这里没有最大高度，所以它会一直长到撞上为止。超过十来行，这份列表就不再能扫读了，而答案是 SearchableMenu——同样那些行，上面加一个过滤器——不是子菜单。" },
  "Popover/01-a-filter-panel": { hash: 'b855d0d1', zh: "一块里面装着控件的面板，而这正是它和 tooltip 之间的全部分别：往提示里放一个字段或一个按钮，那东西就够不着了。label 为这块面板命名，并会在进入时被播报，所以让它说清面板里装了什么，而不是把触发器的话重复一遍。showClose 默认是关的，这里打开是因为面板里装着一份表单——一块唯一出口是「点到别处」的非模态面板，会让一次进行到一半的编辑没有一个明确的收尾。它是真的不模态：这里没有焦点陷阱，所以从最后一个控件继续按 Tab，焦点会走进页面里，而 Radix 会把这读成「焦点跑到外面去了」并关掉面板。" },
  "Popover/02-anchored-elsewhere": { hash: '521d65ce', zh: "这块面板是对着它所编辑的那一行定位的，不是对着打开它的那个工具栏按钮。PopoverAnchor 就是干这个的：没有它，面板会跟着触发器走，从正在被修改的那个东西旁边飘开，而在一张长表格上，那意味着一个悬在屏幕顶端的编辑器，对着靠近底部的一行。触发器仍然是触发器——按 Escape 焦点还是回到它那儿——只是几何位置挪了。" },
  "Popover/03-panel-or-menu": { hash: '4fa4007b', zh: "两块带锚点的面板并排放着，对着区分它们的那一个问题：里面的内容是你要填的，还是你要挑的？一个 popover 的内容是普通的 tab 停靠点，所以四个动作放在一个里面，就是四个停靠点，既没有首字母跳转、也没有方向键——而一个菜单是单个停靠点，两样都有。反过来，菜单装不下一个滑块或一个字段，因为 menuitem 不是一个输入值的地方。两者都 portal 到同一层，也都在 Escape 时关回它们的触发器；两者都不该放进 Dialog 里，那会盖在它们上面。" },
  "SearchableMenu/01-a-filtered-menu": { hash: '33992b09', zh: "一个 DropdownMenu 超过十来行就不再能扫读，而嵌套子菜单只会更糟；这是同一份列表，上面加了个过滤器。它不是 Command 面板——那个是页面级的、模态的、绑在一个按键上的。这个是锚定在某个控件上的，就像它所取代的那个菜单一样，而且它底下就是一个 Popover，所以过滤器开着的时候，背后的页面照样能滚。这些行是 listbox 的 option，而不是 menuitem，因为过滤要求这样：高亮通过 aria-activedescendant 移动，焦点留在输入框里，而菜单做不到这一点。" },
  "SearchableMenu/02-searchable-keywords": { hash: 'bca31c96', zh: "过滤器匹配的是每一行的 value，而这个组件把 action.id 当成了那个 value——所以碰上 act_7f2 这样的 id，看得见的标签什么都匹配不上，敲你眼睛看到的东西，换回来的是空状态。keywords 就是补救，而它同时也是那些「读者会想到、却没人写下来」的词的去处：找 CSV 导出的人会敲 spreadsheet，要回滚一次发布的人会敲 undo。往下面的过滤器里随便敲一个，看着对的那一行留下来。" },
  "SearchableMenu/03-groups-in-order": { hash: 'b1e94963', zh: "分组是把数组走一遍、并且只延长最后一个分组构建出来的，所以一个在别的行之后又出现一次的组名，会产出第二个文字完全相同的标题，而不是并进第一个。把同一组的成员挨在一起，就像这里，而排布完全由你书写它们的顺序控制——这里刻意没有排序属性。还有两样东西跟着行走：shortcut 会在行尾印成一枚键帽，而 destructive 会给它上色。触发器的无障碍名称是 label，不是你作为 children 传进去的那段文字，所以让两者说同一句话。" },
  "Sheet/01-sides": { hash: '59e207e1', zh: "四条边，按阅读顺序命名，而不是按左右：end 在英文里是右边，在阿拉伯文里是左边，靠的是一条自带 rtl 变体的类名字符串，所以没有第二条需要同步维护的代码路径。把这块画布切到 RTL，看着 start 和 end 对调。start 和 end 是一根 min(24rem, 92vw) 的满高列；top 和 bottom 是一条满宽、最高 85vh 的带子。无论从哪条边出来，每个 Sheet 都有一个关闭按钮——不像 Dialog，这里没有 showClose 可以把它关掉。" },
  "Sheet/02-room-to-scroll": { hash: '90773ff8', zh: "Dialog 接不住的那个场景：一份长到要滚动的筛选列表。停靠在 end 上，这块面板拿到的是整个视口的高度，而不是 Dialog 那个 32rem × 85vh 的盒子，读者在列表滚动时仍然守着页面边缘这个锚。注意那些文字：Checkbox 自己一个字都不渲染，所以那些词、以及它们给出的点击区域，是调用处的活儿。页脚两个控件都是 SheetClose：通过 Radix 关闭，才会把焦点放回触发器，而不是把它留在一块已经不在页面上的面板里。" },
  "Sheet/03-a-wide-band": { hash: '1fc9ace0', zh: "又宽又矮的内容属于底边，不属于一根柱子。start 和 end 是一根 24rem 的列，一行四个字段硬塞进去，会折成一条读者要滚的带子；bottom 是满宽、最高 85vh，所以那一行还是一行。它仍然是一个模态对话框——背后的页面被锁住滚动、也不接受指针——所以它适合读者设完就关掉的一个范围，不适合他们要一边看一边干活的面板。那种是 Popover，或者布局里的一列。" },
  "Tooltip/01-an-icon-button": { hash: '5d5ada63', zh: "一个提示，挂在只带图形、不带文字的控件上。提示文字、图标和按钮自己的无障碍名称是一起变的，因为一个前后长得一模一样的复制控件，会让读者为了确认再点一次。让提示和 aria-label 逐字对上：同一个控件有两个不同的名字，就是「名称中的标签」失败项（WCAG 2.5.3），而一个用语音控制的用户念的是他看得见的那些词。提示也不是名称——Radix 遇到触摸指针会提前返回，所以在手机上它根本不会打开，而一个没有自己 aria-label 的图标按钮就是没有名字的。" },
  "Tooltip/02-one-provider": { hash: 'f9d4cff5', zh: "一个 Provider 罩住整条工具栏，这正是它该在的地方：它握着共享的 700ms 打开延迟和 300ms 跳过窗口，于是沿着这一行移动会立刻打开下一个提示，而不是在每个按钮上闪一个各自为政的。没有 Provider，Radix 会抛错，而给每个 tooltip 各配一个 Provider，恰好把那份共享的时序丢掉了。别为了让某一个快一点，就在单个 Tooltip 上设 delayDuration——那只会为那一个触发器覆盖 provider，而一个瞬间弹出的提示，夹在一堆 700ms 的邻居中间，读起来像卡顿，不像强调。设成零更糟：状态会变成 instant-open，而淡入是挂在 delayed-open 上的，于是提示出现时完全没有过渡。" },
  "Tooltip/03-a-shortcut-hint": { hash: 'd9592542', zh: "控件在页面上说明它做什么；提示只补上那个快捷键。tooltip 在触摸设备上够不着，对任何扫读的人不可见，焦点一离开就消失——所以任何读者需要的东西，都不能只活在一个 tooltip 里。还有两条限制值得知道：提示以 11px 等宽字排、宽度上限 16rem，所以一句话会折成一个五行的块，盖住它所描述的那个东西；另外，任何可聚焦的东西都不该放进 content，因为提示不在 tab 顺序里，而且触发器一失焦它就关。放在里面的链接或按钮，只有指针够得着，别的什么都够不着。那种是 Popover。" },

  // ─── Navigation ───
  "Accordion/01-default": { hash: 'a4eaa145', zh: "一份 FAQ：type 用 single 配 collapsible，好让读者打开的那一行还能再关上。没有 collapsible，就没有一个「空」值可以退回去，于是他们打开的第一行，是一行永远关不掉的行。那个标记是加号而不是人字形，这是刻意的——加号说的是「这会展开」，人字形说的是「下面还有」，而在一摞行里，这决定了读者预期的是展开还是导航。给每一行用稳定的东西做 key，别用位置：Radix 是按 value 追踪那个打开项的，所以过滤或重排列表之后，现在坐在那个槽位上的无论是谁，都会站在那儿开着。" },
  "Accordion/02-a-settings-stack": { hash: '68ab1ce3', zh: "type 用 multiple，因为这两行必须相互对照着读——single 会为了打开读者想拿来比较的那一行，把他正握着的那一行关掉。defaultValue 打开他此行的来意所在的那一组。面板是 overflow-hidden 的，正是这一点让它量出来的高度可以做动画，所以里面任何必须逃出这一行盒子的东西——一个 select 的菜单、一个 popover——都必须 portal 出去，否则会在行的边缘被切掉。" },
  "Accordion/03-the-whole-question": { hash: '2b2f5137', zh: "title 既是触发器的无障碍名称，也是面板的，所以一行叫「更多」的行，打开的是一个叫「更多」的区域——而一个在区域之间移动的读者，拿到的是一份什么都没命名的清单。把整个问题写出来。右边那些行在被打开之前就说清了背后是什么，而这也正是那一摞收起来的行仍然可读的原因：一列只有一个词的触发器，是一本没有章节名的书的目录。" },
  "Breadcrumb/01-default": { hash: 'af39843a', zh: "你在哪里，画成一条路径。最后一个面包屑是带着 aria-current=\"page\" 的纯文本，绝不是一条指向自己的链接——自链接是最常见的面包屑 bug，它给读屏软件递上了一条哪儿也去不了的导航。分隔符坐在它们自己的 aria-hidden 列表项里，所以这条路径被读成它的各个条目，而不是「首页 斜杠 组件 斜杠」。label 为这个 nav 地标命名；一个能装下两条路径的页面必须给两条都命名，否则读者会拿到两个都叫 Breadcrumb 的条目，且无从选择。" },
  "Breadcrumb/02-a-deep-path": { hash: '869c6ed9', zh: "一条深到会换行的路径，配一个不是默认斜杠的分隔符。这份列表会换行而不是截断，而这是对的取舍：一条会截断的路径丢掉的那一级，通常正是读者要去的那一级。分隔符无论放什么进去都是装饰性的——它住在一个 aria-hidden 的列表项里，永远不会被念出来。别为了省一行就在手机上把它藏起来。手机恰恰是侧栏躲在抽屉后面的那种布局，而这让这条路径成了屏幕上唯一还在的、能往上走一级的途径。" },
  "Breadcrumb/03-page-header": { hash: 'fb42235b', zh: "那条路径，就在它所终结的那个标题上方。要从当前页面的上一级开始写：一个只有一项的 Breadcrumb，会把那一项渲染成当前面包屑、并且完全没有路径，那是一个在宣告一段长度为一的旅程的地标。除最后一个之外，每个面包屑都需要 href——没有它的那一个会渲染成纯文本，颜色和旁边的链接一样，却既没有目的地、也没有 aria-current，于是它读起来像是读者当前所在的页面，而其实不是。最后一个面包屑和标题重复，不是一处需要修的重复：一个是路径，另一个是页面。" },
  "Collapsible/01-default": { hash: '58f2da4f', zh: "一样东西，自己会打开。CollapsibleSection 是那个组装好的根——触发器、标记和面板都已经接好——也是大多数调用处真正想要的。那个标记是人字形而不是手风琴的加号，这是刻意的：这里揭开的是同一样东西的更多部分，而一个手风琴的行打开的是一个各自独立的答案。这个触发器完全没有被包进任何标题里，和手风琴的不一样，所以拿它们搭出来的页面，会让标题导航无处可停——当这一节确实是一节时，自己加一个标题。另外，别让 title 在「显示更多」和「显示更少」之间来回切：aria-expanded 已经带着状态了，那样这一行会被把状态播报两遍，而且每按一次名字都变。" },
  "Collapsible/02-a-custom-header": { hash: 'db60a316', zh: "松散的触发器和面板，用于一个必须装下不止一个标题的页头——一边一个计数，另一边是那个控件。它们存在，是为了让这个调用处不必直接去找 Radix、再手工把 aria-expanded 和 aria-controls 推导一遍。离开那个组装好的 section，有两件事会变：触发器是一个图标按钮，所以它需要一个自己的无障碍名称；而面板是一个光秃秃的 div，既没有 region 角色，也没有名字。这里设了 defaultOpen，因为它藏起来的东西正是读者来的理由——一块关着的面板是被卸载的，不是被隐藏的，所以它的文字不在页面里，页内查找和打印都够不着。" },
  "Collapsible/03-sidebar-group": { hash: '751c7ba5', zh: "做成受控的，因为必须有外面的东西能把它打开：装着当前路由的那一组，在读者到达时就得已经展开，而一个自己持有状态的组件，是没法被这么告知的。别拿它们搭出一整套——两个 section 之间没法互相关闭，所以读者最后会面对每一组都开着、需要一路滚过去的一列。那份协同正是手风琴的单一 value 买到的全部，也正是一旦有了三组就该改用它的理由。" },
  "NavItem/01-default": { hash: 'fb9bc704', zh: "一列侧栏，其中一行是当前项。active 一步给出三个信号——一层 --stone 填充、中等字重，以及 aria-current=\"page\"——所以这一行在单色打印和低对比度下都还活着，而单靠颜色做不到。图标是 aria-hidden 的，对名称没有任何贡献；children 就是这一行完整的无障碍名称。active 要从路由器的当前路径推导出来，而不是从最后一次点击：一个追踪自己点击的侧栏，是在告诉读者他们在自己按下的那一行上，而不是在他们实际所处的那个页面上。" },
  "NavItem/02-one-current-row": { hash: 'b682bb98', zh: "两个分区，它们之间只有一个 aria-current。别顺手把某一页所属的那个分区也标上：active 意味着 aria-current=\"page\"，而两个 aria-current 等于告诉读者他们同时在两个地方。分组标题是一个标签、不是一行——那些引题不可聚焦，也不会导航。也别把这些行压得更紧；它们坐在 --control-h-sm 上，宽松下 36px、紧凑密度下 30px，而一个比这更小的内边距类，留下的是一列拇指必须瞄准才按得中的目标。这个 nav 是按这个例子命名的，不是按它所描绘的东西。这一页本身就是从一个叫「Documentation」的 nav 里送出来的，而两个同 role、又共用一个名字的地标，任何靠地标导航的人都分不出彼此——包括 axe，它会因此判这一页不通过。" },
  "NavItem/03-router-link": { hash: '5ab1f1cd', zh: "asChild 把这一行交给路由器自己的 Link——这里用一个普通锚点来顶替。它只转发类名和 aria-current，别的什么都不转发，所以要在子元素上把 href 再写一遍：一条不带自己 href 的链接，是一行哪儿也不去的行。图标也要放进子元素里面，因为在这个模式下 icon 属性根本不渲染，于是整条侧栏可能就这么交付出去，看起来像一列图标被悄悄丢掉的行。Slot 只接受恰好一个子元素，这也是为什么图标是放进链接里面、而不是摆在它旁边。" },
  "Pagination/01-default": { hash: '67b6eb85', zh: "二十页，完全受控。要在触发取数的那同一次状态更新里改 page：一个加载下一页却不设 page 的处理器，会让分页器一直标着读者刚刚离开的那一页。当前页是一个带 aria-current 的按钮，而不是一个加了样式的 span，因为一个靠控件跳转的读者必须能找到它——而且那颗填充的药丸是在数字之间移动的，不是一个底色熄掉、另一个底色亮起，前者读起来才像是那个真正变化了的东西。总页数不超过一页时它什么都不渲染，所以一个按固定高度搭的页脚，会在列表变短的那天露出一条空带子。" },
  "Pagination/02-the-edges": { hash: '4d0e5ecf', zh: "同样的二十四页，从两端和从中间各看一次，而分页器通常正是在这几处出错。第一页时「上一页」禁用，最后一页时「下一页」禁用，这会把它们各自从 tab 顺序里拿走，而不是留下一个按了没反应的控件。省略号只出现在序列跳过不止一页的地方——只跳过一页时会把那一页印出来，因为「1 … 3」比「1 2 3」还长，却告诉读者更少。三个分页器就是三个 nav 地标，所以这里每一个都命了名。" },
  "Pagination/03-a-wider-window": { hash: 'ede1972a', zh: "siblings 是当前页两侧各排几个带编号的页。要往上调，别往下调：在总页数低于 2 × siblings + 5 时，每一页反正都会印出来，所以这个属性在短列表上什么都不做，而在长列表上它是你唯一的杠杆。这里两个分页器共用同一个 page，所以点任何一个，两个都动。更宽的窗口只是同样小尺寸的目标更多了，不是更好了——那些药丸是 --control-h-sm，宽松下 36px、紧凑密度下 30px，远低于 WCAG 2.5.5 对指针目标要求的 44px。" },
  "Tabs/01-default": { hash: '653d31a2', zh: "一条标签条、三块面板，靠字符串相等配对——value 里一个拼写错误不会报错，只会得到一个打开后什么都没有的标签页。给根节点一个 defaultValue 或 value：两个都不给，就什么都匹配不上，每块面板都不挂载，页面渲染出来是一条标签条上面顶着一片空白，且没有任何东西说明缺了什么。整条标签条是一个 tab 停靠点；左右键在标签之间移动，Home 和 End 跳到两端。被选中的标签活在 React 状态里、不在 URL 里，所以任何值得被链接到的东西，都需要把 value 提升到一个查询参数里。" },
  "Tabs/02-manual-activation": { hash: 'ed3b33af', zh: "activationMode 用 manual，配一条有名字的标签条。默认是 automatic，于是方向键一边移动一边选中，用方向键横着扫过四个标签，会在读者还没停下之前就发起四次加载——manual 会等 Enter 或空格，而那正是一块要取数、或者要渲染点昂贵东西的面板所需要的。TabsList 默认不叫任何名字，所以一个带着不止一组标签的页面要给每一组一个 aria-label：两个没名字的标签列表，是两个读者无从选择的标签列表。" },
  "Tabs/03-what-gets-hidden": { hash: '57259b69', zh: "把同一句话藏起来的三种方式，以及三种方式共同的后果：被关起来的东西是被卸载的、不是被隐藏的，所以页内查找够不着它，打印只会拿到碰巧开着的那部分，而且三者都不会把当前打开的那个写进 URL。按读者在做什么来选。Tabs 是同一个主题下互斥的几个视图，代价是读者在离开的那块面板里输入过的一切。Accordion 是一组可以互相协同的东西——type 用 multiple 能让两行相互对照着读，而且每一行都往大纲里加一个 h3。Collapsible 是单独一次展开，没有谁可以协同，它也完全不添加标题。任何必须可搜索、可打印的东西，都属于页面本身，敞开着。" },

  // ─── Surfaces ───
  "AppShell/01-columns-and-drawer": { hash: '82cfbe32', zh: "八个具名的部件，而这个名字一个都没有透露。这个框架就是一个栅格，别的什么都不是——md 以上是一根 15rem 的侧栏配一根 1fr 的列，以下是单列。侧栏是一个由 sidebarLabel 命名的 complementary 地标；在手机上它变成一个从「阅读起始的那一边」滑出来的抽屉。它里面，brand 坐在一条细线上方 3.5rem 高的一行里——和顶栏同高，所以两条线跨过列的边界正好接上——而 nav 是会滚动的那一部分。顶栏是粘性的，而且无论你传不传都会渲染，所以一个上面没东西可放的外壳，照样要付 3.5rem 加一条线。切换按钮和遮罩只在手机上出现，而 openLabel 和 closeLabel 就是那个切换按钮全部的无障碍名称。最后是内容井，按页面版心居中，页面内边距也已经加好。" },
  "AppShell/02-a-scrolling-nav": { hash: 'b22a8967', zh: "一根 15rem 的列里放十四行，而品牌仍在屏幕上。把整份列表交给 sidebar 属性，让组件自己的 nav 去滚它：自己搭这根列、把品牌放进会滚动的那部分，那么一份长列表干的第一件事，就是把品牌顶出屏幕。只有 nav 在动，配着那条细滚动条，而品牌那一行和它的细线待着不动。滚一下下面那份列表看看。" },
  "AppShell/03-the-content-well": { hash: '38311649', zh: "内容井已经把它的子元素按页面版心居中，并在两侧提供了页面内边距，所以子元素这两样都不用再加：再拿自己的 max-width 包一层，内容就落到了「中间的中间」。放进去的是页面本身，从 h1 开始——外壳自己不贡献任何标题，而一个所有页面都从 h2 起头的控制台，大纲的顶上什么都没有。这里 contentAs 用 div，仅仅是因为这个预览坐在文档站自己的 main 里面；真实应用里别动它，让这个井去做那个 main 地标。" },
  "Article/01-the-reading-column": { hash: '9f21cc2a', zh: "整片阅读表面，样式是从元素选择器写出来的、不是从类名——因为输入通常不是 JSX，而是从 Markdown 流水线出来的一段字符串，没有组件可以挂类名。用它之前要知道两件事。它的节奏靠的是直接子元素选择器，所以在一串段落外面裹一个 div，哪怕是 display:contents 的，也会让它们全体失去间距。还有，它设定的是版心宽度，不是布局：它自己没有 auto 外边距，所以在一个宽页面里，它会一直贴着起始边，直到某个父元素把它居中。导语由作者用 p.lead 标出来，绝不靠推断，因为一份「谁排在最前就把谁提上去」的样式表，在一篇以图片开头的文章上立刻就错了。" },
  "Article/02-a-markdown-block": { hash: 'ec0ccfa7', zh: "这边写的正文，接着一段不是这边写的字符串，在同一根列里。Markdown 渲染出来的是一个片段、不是一层容器，而这恰恰是它能成立的原因：Article 的节奏靠的是直接子元素选择器，所以两者之间夹任何东西，都会让每一个块失去间距。它也是这一对里安全的那一半——Markdown 解析成组件，整条路径上没有 dangerouslySetInnerHTML，而 Article 的 html 属性设的是 innerHTML，只能用于可信的标记。headingLevelStart 是 2，因为这根列已经以一个标题开场；留在默认值上，这条评论自己的 # 会成为第二个一级标题。" },
  "Article/03-past-the-measure": { hash: '172b5515', zh: "有三样东西被允许越过 46rem 的版心，因为它们在版心里根本读不了：figure、表格，以及任何被流水线标成 m22-wide 的东西。表格自己没有可以滚动的地方，所以六列会把整个页面推得往旁边跑，除非表格被包进 m22-table-scroll——让流水线去做这个包裹，别指望内容一直很窄。把下面那张表往旁边拖，围着它的那根列纹丝不动。也注意标题的深度：h5 和 h6 被排成等宽的引题，而不是更小的标题，所以一份嵌到六层的文档，恰恰在它最需要层级的那个深度上失去了层级。" },
  "AspectRatio/01-reserved-boxes": { hash: 'cc9d45c2', zh: "三个在里面还没有任何东西时就知道自己高度的盒子。这里每个子元素都完全没有固有尺寸——它就是一个空 div——而盒子照样撑住了，因为每一个直接子元素都被拿出常规流、拉伸到填满它。这就是全部机制：里面没有任何东西能贡献高度，所以里面也没有任何东西能破坏这个比例。" },
  "AspectRatio/02-a-grid-that-cannot-reflow": { hash: '17ab716f', zh: "它存在所针对的那个场景：一个封面还没到位的媒体网格。每个盒子已经是对的高度，所以图片落下来时，它们下面的东西一动不动——而那种移动正是 Cumulative Layout Shift 分数在度量的东西。骨架自己没有尺寸；它填满盒子，是因为每一个直接子元素都被拉伸到盒子大小，这意味着加载中状态和加载完状态占据同一个矩形，是构造使然，而不是靠某人手工同步的两个数字。" },
  "AspectRatio/03-the-ratio-wins": { hash: '7fa776c5', zh: "内容装不下时这个盒子会做什么，而这正是那种没人会去读、直到它咬人为止的取舍。每一个直接子元素都被拿出常规流，容器把溢出藏起来，所以比盒子长的内容会被裁掉，而不是被允许把高度顶开——比例是那个承诺，而这就是承诺被兑现的样子。当那些字必须可读时，给子元素它自己的滚动，就像第二个盒子那样；当它们不必可读时，就去拿一个能长大的盒子，而不是一个不能的。" },
  "Calendar/01-a-range": { hash: '2bb1ba9e', zh: "一个月，画成一张日期网格，上面横着一段区间。淡色的底落在单元格上，而两端的填充落在按钮上，正是这一点让一段区间读起来像一条两头是圆的带子——也正是这一点让一段只有一天、两端合一的区间仍然是圆的。要通过 classNames 的插槽去标注可用性，别去给日期按钮加样式，否则那个端点的背景会被压平。标题栏是一个按钮，不是两个下拉框：一个日期本来就是这么说出来的，而把它拆开，等于在一个 250px、还要装下两个箭头的行里塞进四个控件。点开它，月份和年份的选择器会原地画在网格的位置上、尺寸分毫不差，按 Escape 焦点回到标题栏。labels.labelNav 为月份箭头那个工具栏命名。不管它，页面上每个日历都是一个叫「Navigation bar」的 nav——那是 react-day-picker 自带的字符串——而一页上三个例子就是三个没人分得出的地标。" },
  "Calendar/02-one-day": { hash: '98eafaed', zh: "一次一天，以及那两个绝不能长得一样的记号：today 是一圈环，selected 是一块填充。一个是关于这本日历的事实，另一个是读者做出的选择，所以一套把两者画成同一个样子的系统，会让读者分不出自己到底选了什么。相邻月份的日期会显示出来并调暗，而不是留成空洞。别给这张网格一个固定高度——大多数月份是五周，有些是六周——也别用 w-full 把它拉开：它是 w-fit，排的是固定 36px 的列，所以一个宽度类只会让同样这张网格坐在一个更宽盒子的起始边上。要在表单里选日期，这东西属于 DatePicker。labels.labelNav 为月份箭头那个工具栏命名。不管它，页面上每个日历都是一个叫「Navigation bar」的 nav——那是 react-day-picker 自带的字符串——而一页上三个例子就是三个没人分得出的地标。" },
  "Calendar/03-disabled-days": { hash: '8f5c3d4b', zh: "周末和 7 号之前的一切都被拒掉，网格也不会让你提交这样一个日期：disabled 收的是匹配器——星期几、一个日期区间、一个判定函数——它会把命中的按钮调暗、而不是把它们移走，于是这个月保住了自己的形状，读者也看得见某一天为什么不可用。这里也是一个可用性视图的起点：通过 classNames 的插槽去标记单元格，别去给日期按钮加样式，这样那些标记就仍然和区间的淡色底兼容。startMonth 和 endMonth 限定标题栏的选择器能走多远；默认是前后各十年，正好是年份网格的一页，完全不用翻页。labels.labelNav 为月份箭头那个工具栏命名。不管它，页面上每个日历都是一个叫「Navigation bar」的 nav——那是 react-day-picker 自带的字符串——而一页上三个例子就是三个没人分得出的地标。" },
  "Card/01-variants": { hash: '9739d603', zh: "有边界的那种表面，和唯一那种反色的，并排放着。两者底下都没有阴影：一张需要读起来是「浮起来」的卡片就是 plate，而它靠反色来分离，因为这套系统没有一档可以把它抬起来的高度阶梯。plate 一屏花一次——一整排 plate，就是一整排没有底可供反色的东西。里面也要用 CardTitle，别用你自己的标题：plate 会把 --card-title 重新指向 --on-feature，而一个直接读 --ink 的标题，在那块底上对比度是 1.25:1，在这个唯一以「看起来不一样」为全部职责的变体上，它是隐形的。" },
  "Card/02-a-real-control": { hash: 'abfb479a', zh: "一整张卡片当作一个目标使用，而盒子上没有 onClick。一个挂了点击处理器的 Card 就是一个挂了点击处理器的 div：不可聚焦、不会被播报、键盘够不着。补救办法是在它里面放一个真的控件，用一层绝对定位的覆盖层铺满整个盒子——于是被播报出来的是一条以标题为名字的链接，焦点环有东西可落，而整张卡片仍然是命中区域。要让这个成立，盒子需要 position: relative，而任何读者还必须能单独点到的东西，都得坐在覆盖层之上。" },
  "Card/03-a-ruled-grid": { hash: '3ecfafab', zh: "flat 是给那种「容器已经在单元格之间画好了线」的卡片用的底——三张 outlined 卡片放进一个带边框的网格里，是本来只要一圈边框、结果画了三圈。这里还有两件事是承重的。这个盒子自己不带内边距，所以直接丢进去的子元素会贴着边：CardBody 才是提供它的那个。另外 CardTitle 默认是 h3，紧跟在上面那个 h2 下面时这是对的，而一旦一个十二张卡片的网格上面没有任何标题可供它们归属，它就错了——用 as 说明这里真正的层级是哪一级。" },
  "DescriptionList/01-record-fields": { hash: '02bbcf16', zh: "一条记录的正面。这段标记是真正的 dl/dt/dd，正是它告诉读屏软件「Owner」命名的是旁边那个值——一堆 div 拼出来的网格看起来一模一样，却什么都没说。值是一个节点，所以一个状态是一枚 Badge，一个日期是一个 Timestamp，而不是两个手工格式化出来的字符串。" },
  "DescriptionList/02-row-and-stacked": { hash: '7759ce65', zh: "同样三个字段，在两种布局下各来一遍。row 是记录页的形状——标签沿着一条边对齐，读者是在扫它们而不是读它们——而它在 sm 断点以下会塌成一列，因为手机上一根 12rem 的标签列，留给值的宽度大约八个字符。stacked 在任何宽度下都把值放在它的标签底下，而这是那种「因为设计如此、而不是因为视口而窄」的容器的答案：一张卡片、一根侧栏、一个 popover。按容器选，不是按字段个数选。" },
  "DescriptionList/03-a-metadata-rail": { hash: '5ea9b166', zh: "它被造出来所针对的那个形状：一个详情页，左边是记录本身，旁边一根边栏放它的元信息。这根边栏是 stacked 且不带分隔线的——它本来就已经在一根带边框的列里面，而在一个盒子里再来一套细线，是一个装成表格的网格。边栏里的每样东西都是关于这个东西的事实，而不是这个东西的一部分，而这正是判断什么该放这儿时要划的那条线：标题和正文是这条记录，而负责人和最后一次部署，是这一页关于它所知道的事情。" },
  "ScrollArea/01-a-bounded-log": { hash: '2fd6e030', zh: "根节点上的那个高度，才是让这一切发生的东西：没有它，盒子和内容一样高、什么都不会溢出，而这个组件给页面添加的全部，就是一个键盘停靠点。那个停靠点也正是拿它而不是拿一个光秃秃的 overflow-auto 的理由——Radix 让视口保持可聚焦、让滚动条可操作，于是首屏之外的一切不用鼠标也够得着。label 之所以必填，也是同一个理由：一个没名字的键盘停靠点，播报出来只有一个「group」，别的什么都没有。页面级或正文的滚动，用 scroll-slim 这个工具类更轻，连组件都不需要。" },
  "ScrollArea/02-both-axes": { hash: '2a198e35', zh: "orientation 默认就是 both，这里把它写出来，是因为那个没有滚动条的轴会被设成 overflow: hidden——所以一旦把它收窄成 vertical，比盒子更宽的内容就不只是没有标记，而是被裁掉了，没有任何按键、任何手势够得到。只有当某个轴确实不可能溢出时，才去收窄它。只有两个轴都在时，才会有那个角上的方块。也别把它们在同一个轴上互相嵌套：内层视口会一直吃掉滚轮，直到它自己到底，所以一个对着外层列表的读者，动的会是里面那个。" },
  "ScrollArea/03-a-permanent-bar": { hash: '56f7702d', zh: "type=\"always\" 无论指针在不在里面都把两条滚动条画出来。默认是 hover，而平台自己的滚动条是藏起来的，所以静止时屏幕上没有任何东西说明这个盒子会滚——当最后一行明显被切掉一半时，这没问题；而当内容碰巧正好在边界处结束时，这就是个陷阱，而这份列表差不多就是如此。别在它上面再搭一套拖拽滚动：那个滑块刻意是 touch-none 的，而视口是一个真正的溢出容器，所以触摸拖动、惯性和滚轮已经是平台的了，而且表现符合读者的预期。" },
  "Toolbar/01-form-actions": { hash: '70cb8e6d', zh: "一片工作表面脚下那条动作栏。底色是不透明的 --paper，而不是一层模糊，因为内容会从它底下滚过去——任何半透明的东西，都会把表单的最后一行摆到提交按钮后面。它是一个具名的 group，不是 role=\"toolbar\"：那个角色承诺了控件之间可以用方向键走，而这里没有任何东西实现了它们。" },
  "Toolbar/02-a-filter-bar-on-top": { hash: '1f438f12', zh: "同一个组件，在另一条边上。position 用 top 会把这条栏粘在它滚动容器的头部，并把细线挪到底部，于是一个在长列表里往下滚的读者，始终握着塑造了这份列表的那些控件。align 用 between 是这个形状在这里的需要：筛选条件从起始边读起，动作坐在末端，于是这是一条栏，而不是一行筛选加一行按钮。一个粘性元素是粘在它的滚动容器里面的，所以需要高度的是容器，不是这条栏。" },
  "Toolbar/03-every-control-is-a-tab-stop": { hash: 'e4b14310', zh: "一条批量操作栏，以及这个角色是 group 而不是 toolbar 的理由。ARIA 的 toolbar 契约是「一个 tab 停靠点，里面的控件之间用方向键移动」；这里没有实现漫游 tabindex，所以声明那个角色，等于告诉用读屏软件的人去按一些什么都不会发生的键。作为一个具名的 group，每个控件都保住了自己在 tab 顺序里的位置——Tab 依次到达归档、删除、清除——而这条栏仍然会被按名字播报，这也是为什么 label 是必填而不是可选。" },

  // ─── Data ───
  "BarList/01-default": { hash: '91ab261f', zh: "这份排名列表最朴素的样子：八行，条形画在名字后面，而不是名字旁边。而这正是一张水平条形图做不到的事——它要拿三分之一的宽度去放分类轴，而把那根轴上的一个名字对应到它的条形是两步，直接从条形上读出名字则是零步。除非 sort 另有说明，各行按降序排列，而刻度的上限取自其中最大的那一个，所以这份列表自己读是可读的，和第二份对照着读就不是了。" },
  "BarList/02-limit": { hash: '0c9aff23', zh: "limit 保留前三行，并把余下的五行汇总成一行 Other，而不是把它们丢掉。一个悄悄丢掉长尾的「前三」歪曲了整体，还让读者没有任何办法知道这件事发生过；那行 Other 才是让这一列数字加起来还等于点什么的东西。领先的三行还带着 href，这让名字本身成为链接——条形是同一个单元格上的背景，所以给一行加链接，不会给读屏软件多添一个要走过去的东西。" },
  "BarList/03-a-shared-ceiling": { hash: '66d8c99a', zh: "两份必须对照着读的列表，所以两份都被给了同一个 max。放任它自己推导，每一份都会拿自己最大的那一行当上限，于是 Enterprise 在两边都填满了自己的轨道——一个翻了一倍还多的季度，画出来会和一个原地踏步的季度分毫不差，而页面上不会有任何东西说明这一点。formatValue 让这些数字变成金额；默认是坐标轴用的那套紧凑写法，那对一个访问次数是对的，而对一种货币则什么都没说。" },
  "BigNumber/01-default": { hash: '9d876238', zh: "三个变化量，每一个的方向都由调用处声明，而不是从符号推断出来：错误数下降 12% 是好消息，收入下降 12% 不是，而没有哪个组件分得清自己手上握的是哪一个，所以是 intent 决定了一个变化被染成 ok 还是 danger。箭头和给读屏软件的那个词承载着同一个解读，正是这一点让它在灰度下、在强制色彩下、以及对一个分不出这两种色调的读者面前都还可读。变化量为零就是 flat——一个横向的箭头，完全不上色——这也是为什么一个 neutral 的 intent 仍然有话要说。" },
  "BigNumber/02-with-sparkline": { hash: '30147ec1', zh: "每块仪表盘都会去拿的那种搭配：数字回答「多少」，它底下那条走势回答「怎么走到这儿的」，而不必为一根没人去读的坐标轴花掉一整块面板。children 就是那条走势的去处，位于标签、数字和变化量之下；这条 sparkline 收一个自己的 label，因为它上面那个标题命名的是另一个事实。一旦这个形状必须被精确读出，就立刻去拿 LineChart——按设计，一条 sparkline 没有任何坐标轴可供参照。" },
  "BigNumber/03-points-and-a-missing-value": { hash: 'b90bdf5d', zh: "这个组件拒绝去猜的两件事。变化量的默认格式是带符号的百分比，所以 0.6 会印成 +60%——对一个比值这是对的，而对一个本身就是百分比的比率则是错的，那里的变化是 0.6 个百分点；format 就是调用处用来说明自己手上握的是哪一种的东西。第二张卡片还没有数字、也完全没有变化量：value 收的是节点而不是数字，正是为了让调用处能在那儿印一个破折号，因为零是一种断言，而一个「无可对照」的变化没有方向可指。" },
  "BulletChart/01-default": { hash: '8534d8d7', zh: "四个度量，共用一把 0 到 100 的刻度，于是那些区间带在每一行上含义相同，各行之间既能相互比较、也能各自跟自己的目标比。条形是测量值，横穿它的那道线是目标：两类不同的数，这也是为什么目标不是画成旁边的第二根条。那些区间带是某个人做出的判断，却用和测量值同一种笔墨画出来，而且它们会压缩——一个压线过关一分的值，和一个甩开三十分的值，落在同一条带里，所以一条带回答的是「这个数能不能接受」，永远不是「差了多少」。没有渲染引擎，也没有状态：每一行都只是一把用普通 HTML、按逻辑属性排出来的线性刻度，可以服务端渲染，并且在从右往左的文档里能正确镜像，而一张画在用户坐标系里的 SVG 做不到。" },
  "BulletChart/02-per-measure-scales": { hash: 'ef210bba', zh: "四个度量，既不共用单位也不共用范围，各自带着自己的 domain 和自己的 ranges——正是这一点让一个以毫秒计的延迟，能和一个百分比待在同一个块里。只有当这些度量共用一把刻度时，共享的区间带才有意义，所以这里图表级的 ranges 和 domain 干脆都不写。showScale 默认是关的，这里由那个开关打开，因为四个不同的 domain 摞在一起时，读者没有别的办法知道一条轨道的两端各值多少。" },
  "BulletChart/03-empty": { hash: '1e4adde4', zh: "一个状态页在没人填过它的那个早晨所处的状态——一个新季度、一个什么都匹配不上的筛选、一个没有历史的账户——而这也正是大多数图表库会回给你一摞空轨道的那个状态，读者分不出它和一张加载失败的图表有什么区别。无论如何，这个图形都保住了它的标题和描述，所以这一页仍然说得清缺的是什么。文案说的是发生了什么，而不是「暂无数据」，而且它带着那个唯一能改变现状的东西：一个没有动作的空状态是一条死路。" },
  "Heatmap/01-default": { hash: 'a167b178', zh: "顺序型刻度，给那种只会往上走的值用——一个计数、一段时长、一个体量。这道渐变只有一个色相，由浅到深，因为明度是唯一一条眼睛不用查图例就能读出次序的通道；把色相花在量级上是热力图历久弥新的错误，而这里已经没有色相可供搞砸了。domain 是从各个单元格推导出来的，这对一张独自阅读的网格是对的，而一旦旁边摆上第二张网格，它就错了。" },
  "Heatmap/02-diverging": { hash: '94bd4b1e', zh: "发散型读的是距中点的距离，所以两个方向都会加深，而刻度的中间就是页面本身——这是给差值、给残差、给任何「零是一条真实边界、而不只是底部」的东西用的刻度。domain 是刻意对称钉死的：推导出来的话，它会从最低的读数跑到最高的读数，把中点丢在极值碰巧落到的地方，而不是落在这把刻度所铰接的那个零上。没有读数的那一周画成一圈虚线轮廓，而不是最浅的那格，因为空缺不是零；而 showValues 会把淡色底压在渐变的 35% 以内，好让印上去的数字在每一格上都能从自己的背景里脱出来。" },
  "Heatmap/03-shared-domain": { hash: '1c107934', zh: "两张只有对照着读才有意义的网格，所以两张都被钉在同一个 domain 上。推导出来的话，每一张都会从零跑到自己最大的那个读数，两张都会用满整道渐变——法兰克福三分钟的峰值，画出来会和悉尼十分钟的峰值一样深，而这正是共享图例唯一补不了的那个失败。formatValue 把单位带进单元格：没有它，一个班次会把自己播报成 480，有了它则是 8m，而对任何通过表格、而不是靠眼睛够到这些单元格的人来说，这是一个数字和一个读数之间的差别。" },
  "Sparkline/01-variants": { hash: '8aa17521', zh: "同一条走势可以被画成的三种标记：line 读的是趋势，area 把这个趋势往体量上压，而 bars 把各个读数分开，那是一个离散计数想要的。三种按设计都没有坐标轴、没有网格、没有标签——任何一件能让它回答「到底是多少」的外围装置，同时也会让它大到没法待在行内，而那本来是去拿它的唯一理由。确切的数字改由 value 印在走势旁边，而在 line 和 area 上，最后一个点会画成一个圆点，因为通常被问的就是它。" },
  "Sparkline/02-in-a-table": { hash: '557e8ecf', zh: "一列 sparkline，每一条都钉在同一个 domain 上。这就是全部的教训：在按行各自推导的 domain 上，每一条走势的波峰和波谷都停在同样的高度，于是一个腰斩的渠道和一个翻倍的渠道画出同一幅图——这是一张 sparkline 表格变成主动误导的唯一方式。每条走势还带着自己的 label，因为读屏软件会在四个单元格里遇到四条，而这一行里没有别的东西为它们命名。" },
  "Sparkline/03-not-enough-data": { hash: '6be27d3e', zh: "当没有形状可画时，一条 sparkline 会做什么。少于两个点时，它印出自己的 label，后面跟着「数据不足」，而不是画一个标记：一个读数不是趋势，而把单个值对自己做归一化，会把点放在算术碰巧落到的地方，读者会把它当成一次测量。这是一个新项目第一天所处的状态，也是一个很窄的筛选条件不断触到的状态，所以值得在它出现在表格第四十行之前，先知道它长什么样。" },
  "Table/01-a-sortable-column": { hash: '259ee70a', zh: "排序是逐列选择开启的，因为一张每个表头都是按钮的表格，会招人去排一列数据根本没法排序的东西。一个可排序的表头会在 th 里面渲染一个真的 button——单元格上的点击处理器不可聚焦、也不会被播报，那样排序就只对鼠标存在、对别的什么都不存在——并且根据 sortDirection 设置 aria-sort，而那是读屏软件得知这张表被排过序的唯一途径。每个表头各带各的 aria-sort，没有任何东西在协调它们，所以排序换列时，记得把其余的重置成 none。caption 是必填的，且默认隐藏：它既命名这张表，也命名那个滚动区域。" },
  "Table/02-borders": { hash: '2b768d96', zh: "四种边框设置用在同样两行上，于是变的只有那些线。rows 是默认值，也是沿着一列往下读时的正确答案：记录之间一条细线，没有任何东西跟眼睛正在追踪的那条线抢。grid 加上一张密集数字表所需要的竖线；bordered 在整体外面画一圈边，给那种散落在页面上、而不是待在一张本来就有边框的卡片里的表格用。任何一档设置下都没有斑马纹——在一套单色系统里，一条带底色的行是第二片表面，在跟页面的底争。density 用 compact 会把行内边距从 14px 减半到 8px，而那正是一张几乎全是数字的表格想要的。" },
  "Table/03-a-sticky-header": { hash: '43e1cfc1', zh: "stickyHeader 需要一个有界高度，而那个容器并不归这个组件所有。每一个属性，包括 className，都落在 table 元素本身上——不是落在包着它的那个会滚动的 div 上——所以只有一个施加约束的父元素，才能给那个 div 一个可以粘住的范围。这就是行得通的那种排布：一根定高的 flex 列。滚动区域既是一个 flex 项、又是一个滚动容器，所以它的自动最小尺寸是零，会缩到给它的那个高度。在一个普通块级容器上写 max-height 做不到这件事，而表头就只会跟着别的一切一起往页面上方跑掉。" },
  "Table/04-seven-columns": { hash: '628be4c1', zh: "七列、印出来的 caption，以及行表头。showCaption 会把那个隐藏的 caption 变成表格上方的引题；无论哪种，同一个字符串都是滚动区域的无障碍名称，所以进去的路上会听到一次，从表格那儿又会听到一次。在每一行的第一个单元格上传 scope=\"row\"——TH 写的是 scope=\"col\"，而你的属性是在它之后摊开的，所以这个覆盖会生效；没有它，每个行表头都在宣称自己是一列的表头。这里没有任何东西会在手机上重排：这个区域在一条细线栏后面横向滚动，而首屏之外的那些列，只有想明白了它会滚的读者才够得着。把这块画布收窄看看。375px 下的七列需要的是另一种呈现方式，不是更小的字号。" },

  // ─── Charts ───
  "AreaChart/01-default": { hash: '1984fed1', zh: "两条序列，两种纹理。在单色的默认设定下，主要把它们分开的是填充，灰阶只是配合，而这也正是能在灰度打印和色觉障碍读者那里活下来的东西。当曲线底下那个量本身就是要读的东西时，去拿面积图，而不是折线。" },
  "AreaChart/02-fill-variants": { hash: '5f9ffbb9', zh: "六种填充，在同一条序列上轮了一遍，好让差别可比。在没有色相可花的地方，这是那条先于灰阶把两片面积分开的轴，所以一张不止一片面积的图，应该先变它、再去变别的。gradient 是默认值，会朝着坐标轴消散；solid 读起来是一条带子而不是一道斜坡；而那三种纹理，是在灰度打印里仍然能把两条序列分开的那几种。" },
  "AreaChart/03-stroke-and-curve": { hash: 'a1fec201', zh: "线条本身的两条轴，而它们处在不同的层级上：strokeVariant 属于某一片面积，curveType 属于整张图。animated-dashed 是一个 SMIL 循环，样式表里的 reduced-motion 规则够不着它，所以组件替它把关，并且是整个去掉、而不只是放慢。curve 是那个会改变这张图所宣称的内容、而不只是它长相的设定——step 说的是两行之间什么都没测过，monotone 说的是这个量平滑地移动过，而那些行本身没法告诉你哪一个是真的。" },
  "AreaChart/04-stacking": { hash: 'd0a0e221', zh: "三个不同的问题，不是三种长相：default 比较两条序列，stacked 读它们的合计，expanded 读它们的占比——而第三种下，数值轴会自己切换成百分比。堆叠藏起来的是基线：只有最下面那条带还坐在一条直线上，所以它上面每一条带都是一个形状，其起伏有一部分来自它底下那条，这也正是为什么「移动端有没有增长」仍然要用 default。" },
  "AreaChart/05-dots-and-reveal": { hash: 'db09f6fb', zh: "标记点和入场擦除是同一个主题，因为它们共用一张遮罩：它同时盖住面积的填充、它的描边和它静止时的圆点，于是标记点是跟着线一起到达的，而不是抢在它前面蹦出来，后者正是把两者分开做动画时会发生的事。图上那个 key 才是重播这次揭示的东西——单独改 animationType 不会让这片面积重新挂载。一次揭示是一张逐帧动画的 SVG 遮罩，也是这个包里最重的东西，这也是为什么 none 是一个正经答案，以及为什么操作系统的减少动效偏好也落在这里。" },
  "AreaChart/06-brush": { hash: '5464de7d', zh: "三十二天已经超出一张图能一次显示的范围，而 brush 是那个既让整条序列保持可见、又让读者挑出其中一段的答案。它是一个子元素、而不是一个 showBrush 属性，而且两个手柄都是真的滑块控件：Tab 到其中一个，方向键就能一步步移它，Home 和 End 把它跳到两端，而它移植自的那个形态是只认指针的。代价是图表下面多出一张缩微的图，以及它占掉的高度，所以一张只有六行的图并不需要它。" },
  "AreaChart/07-loading": { hash: 'c70dfdfd', zh: "一张真实仪表盘图表大半辈子都待着的两种状态之一，也是那个说「还没有」而不是「这里什么都没有」的状态。骨架的各行是按行下标做种子生成的，不是拿 Math.random 画的，所以服务端和客户端渲染出同一个形状，一张加载中的图表不会记下一条水合不匹配——而且它保住了图表量出来的高度，所以数据落下来时页面不跳。在 prefers-reduced-motion 下，那道行进的高光会被换成一层平铺的淡色。" },
  "AreaChart/08-chroma-palette": { hash: 'b3ff4ffa', zh: "往里加色相的那条获准的路，也是唯一的一条：任意一个祖先上的那个属性，会把八个序列自定义属性重新指向一套在两种底色上都验证过的分类调色板，而下面这张图里没有任何地方提到过颜色。另一条路是在 config 的 colors 数组里手挑十六进制色值，而那正是一套未经验证、对色觉障碍不友好的调色板诞生的地方。浅色那几档里有三档在纸色上低于 3:1，而这正是「一条序列以上图例就不是可选项」这件事被写下来的理由。" },
  "AreaChart/09-annotations": { hash: 'd24feca6', zh: "三层，按编辑型制图沉淀下来的顺序绘制，而这个顺序由包来固定、不由它们被组合的先后决定：色带是背景语境，坐在网格后面；参考线是关于数据的一个断言，坐在标记之上；而注记解释这两者，坐在一切之上，包括 hover 出来的那个点。大多数看起来需要第二条序列的图表，其实需要的是一条参考线——「我们在线上还是线下」，一条阈值一眼就答得了，第二条序列答不了。" },
  "AreaChart/10-empty": { hash: '44064bba', zh: "一张真实仪表盘一周之内就会到达的另一种状态——一个什么都匹配不上的筛选——也是值得为它写一句话的那一种，因为一对空坐标轴和一张加载失败的图表毫无分别，于是读者刷新页面，它还是空的。它和加载骨架是两回事：那一个说「还没有」，这一个说「这里什么都没有」，而且它通常还附着一件接下来能做的事。想保留光秃秃的坐标轴，就传 empty={false}，用于那种「空本身就是结论」的图。" },
  "AreaChart/11-sonify": { hash: '8a834c17', zh: "那张隐藏的数据表把每一个数字都交给了用读屏软件的人，那是可及性，却不是一个形状——六个数字一个一个念出来，说不出三月凹下去过，而一串音调能，只要不到两秒。这个控件在第一个音符之前，会先播报点的个数、分类轴的跨度和两个极值，于是这段旋律是一次测量、而不是一条轮廓。在有人按下按钮之前，什么都不会播放：这里没有 autoPlay 属性，也没有任何 effect 能启动一次播放。" },
  "BarChart/01-default": { hash: '1ca16189', zh: "两条柱状序列共用一根分类轴，而这正是分类是离散的、不是连续统时该拿的形状。每条序列按声明顺序取灰阶上的下一个档位，所以隐藏其中一条，绝不会把剩下的重新上色；第二条带着一层斜纹，因为光靠一档灰，是一个太单薄的、要读者在脑子里记住的东西。这也正是为什么一条序列以上时，图例不是可选项。" },
  "BarChart/02-fill-variants": { hash: '3feef0d0', zh: "填充一根柱子的六种方式，在同一条序列上轮了一遍，好让它们可比。stripped 是最经得起密度考验的那个：它只把顶上两个角做圆，并在一层淡色底之上印出 2px 的序列色帽，所以到二十根柱子时它仍然读起来是二十个各自不同的值，而一块实心方块那时已经变成一堵墙了。其余几种是拿分量换纹理，而在没有色相可花的地方，这就是那个先于灰阶把两条序列分开的东西。" },
  "BarChart/03-stacking-and-orientation": { hash: '8d62431f', zh: "两个会互相影响的选择。堆叠在每一档上问的是不同的问题——default 比较、stacked 合计、percent 占比——而 orientation 关乎的是分类名：「Organic search」放在一行旁边可以横着读完，放在一根柱子底下就得旋转或者截断。坐标轴会跟着换，而这是唯一需要调用处自己动手的那一部分：分类的 dataKey 从 X 轴挪到 Y 轴，而那根轴需要一个宽到能装下最长标签的宽度。" },
  "BarChart/04-emphasis": { hash: '28aece14', zh: "说「就是这一个」的三种方式，并排放着。一张单色图表没有更亮的颜色可以去拿，所以 glowing 在那条作为这张图重点的序列背后放一圈光晕；buffer 把最后一个分类画成一片空心斜纹，那是「这一期还没走完」的惯用画法，和别的柱子一样高、却明显不是同一类事实；而 hover 高亮会把指针没落在上面的每一根柱子降到 30%。最后这一种是由指针驱动的，所以它永远不能是唯一承载某个结论的东西。" },
  "BarChart/05-interaction": { hash: '81d0a724', zh: "读者能拿一张图表做什么，而不是它长什么样。图例条目是带 aria-pressed 的真按钮，所以 Tab 够得到它们，Enter 能开关一条序列——一个加了点击处理器的、带样式的 div 两样都做不到——而柱子可以点击选中，也是同一个理由。tooltip 的底色和它的圆角是两个值得暴露出来的旋钮，而 defaultIndex 会在还没有任何 hover 之前就把它开在某一行上，于是这块面板在截图里、以及对一个从不移动指针的读者来说，都是可读的。" },
  "BarChart/06-brush": { hash: '1877383c', zh: "二十八根柱子是一根分类轴不再可读的地方，而 brush 让整条序列留在视野里，同时让读者从中挑出一段。下面那条带子用柱形标记画的是同样那些行，于是「你在从中挑选的东西」看起来就像「你在读的东西」——一个只显示缩放结果的控件做不到这一点。上面那张图随后只渲染被选中的那个窗口，所以一切读取可见行的东西，都跟着这个选择一起走。" },
  "BarChart/07-loading": { hash: '5ff36d6c', zh: "骨架，柱子的根数是手工设的。loadingBars 决定画几根柱子，不设的话默认是十二根，而这在柱状图上比在折线图上更要紧：十二根骨架之后跟着六根真柱子，读起来像是这张图丢了一半数据。标记被换掉了，但量出来的高度保住了；而这个开着的时候，旁边组合进来的 brush 或工具栏会被抑制，因为此刻还没有东西可供你从中挑一个窗口。" },
  "BarChart/08-value-labels": { hash: '65f98801', zh: "把数字印在标记上，以及该印多少个。每个点都印一个数字，是一张图表被毁掉最常见的方式——那些标签会跟它们所标注的形状打架，读者两个都丢——所以默认是 last，即那个读者本来会顺着描回坐标轴去找的唯一一个值。extremes 才是「哪个月最糟」真正在问的东西；而 all 只有在「五六根柱子和它们的确切数字」就是全部重点时才配有一席之地，过了那个点，它就是一张穿着图表外衣的表格。" },
  "BarChart/09-sonify": { hash: 'd604e406', zh: "屏幕上两条序列，值得去听的只有一条。keys 收窄这次播放，因为播放是顺序的——每条序列完整播完，一条接一条——而听的人很少想要全部。formatValue 决定那段播报怎么念，于是范围是按坐标轴印出来的单位读出来的，是「从 $9,200 到 $31,400」而不是「9200」；不写它，念出来的范围就退回默认的刻度格式，而那并不是旁边那根坐标轴上的那个。" },
  "BarChart/10-toolbar": { hash: '27ebc810', zh: "工具栏最多五个控件，而且不附带溢出菜单，这既是一个尺寸上的决定，也是一个设计上的决定：一行永远不会超过五个 44px 目标的东西并不需要它，而那个菜单会让每一张笛卡尔图表的每一个使用者，都要背上图表静态引入的那个 Radix 菜单。一张放在窄卡片里的图表改成少放几个控件——zoom={false}，或者只留一种导出格式而不是两种。这两个文件刻意不是同一幅画：PNG 是此刻这张图的样子，会跟着缩放走，而 CSV 永远是完整的数据集，就像这个图形隐藏的那张数据表一样，因为一份悄悄少了你缩放时掠过的那些行的表格，是一种你看不见的数据丢失。" },
  "BoxPlot/01-default": { hash: 'b411675c', zh: "四个分布，占的墨水和四根柱子一样多，交进来的是原始观测值——图表会把它们排序、按 R 的 type 7 取四分位数，并让每根须停在仍落在 Tukey 1.5 倍 IQR 栅栏之内的最极端读数上，于是悉尼的 402 和法兰克福的 588 会掉出来变成点，而不是把须拉到一个没人测到过的值上。五个数说不出来的是形状：一个有两个峰的地区，画出来的箱子和一个中心落在同一位置的平滑分布一模一样。它们也说不出样本量，因为十个读数画出的箱子和一万个读数画出的箱子长得毫无分别——而这正是 count 和 BoxPlot.Boxes 的 notch 存在要修的东西。数值轴没有锚在零上，因为为了在柱长上诚实而把它拽到零，会把每一个箱子压平成一条像素带。" },
  "BoxPlot/02-orientation": { hash: 'cea7c523', zh: "长分类名正是 horizontal 存在所针对的场景：放在柱子底下，ap-southeast-2 得旋转才装得下，而放在一行旁边就能横着读完。坐标轴只组合一次、然后自己解析自己——XAxis 和 YAxis 各自读取 orientation，在分类角色和数值角色之间互换，而网格也会翻转它画哪一组线——所以那个开关只改一个属性，树里别的什么都没变。这也是为什么这里两根轴都没带 label：一个单位属于哪根轴，是随 orientation 变的，而一个钉在 YAxis 上的标签，最后会去命名那些地区。" },
  "BoxPlot/03-notched": { hash: '454f1bb4', zh: "已经算好了才送来的摘要，这是它的另一种形态——一个数仓回给你的是分位数，从来不是原始行。count 是画一个缺口所需要的东西：那个收窄是 1.58 倍 IQR 除以根号 n，所以两个不重叠的缺口大致是一个「这两个中位数不同」的 95% 检验，而 Variant B 的缺口很宽，是因为它的样本是 190，对着别人的 4,000。这正是朴素的箱子所藏起来的那个比较，因为 190 个读数画出的箱子和 4,200 个读数画出的箱子长得毫无分别。这个缺口被夹在四分位数以内，而不是被允许把箱子折得里外翻转，所以一个小到做不了这个比较的样本，会收成一条细缝，而不是读起来像一处渲染故障。" },
  "ComposedChart/01-default": { hash: '7ac46907', zh: "柱子和一条线共用一根坐标轴——这是「这个体量，以及它变动的速率」的那个形状。永远只有一根数值轴：两个尺度不同的度量该分成两张图，或者一起换算到一个共同的基准上，因为第二根 y 轴让作者可以选择那些线在哪里交叉，而那是一张图表能做的最误导人的一件事。它暴露出来的这根轴就是唯一的一根，这是设计使然。" },
  "ComposedChart/02-variants": { hash: 'da589182', zh: "柱子那一半带着和普通 BarChart 一样的六种填充，线那一半带着一样的三种描边，所以组合图不是要你去学的第三套词汇——dot 插槽在线里面组合的方式，和在 LineChart 里一模一样。这也正是该拿它、而不是把两张图叠在一起的理由：一份 config、一根轴、一套 variant，以及一个会为同一行同时报出柱子和线的 tooltip。" },
  "ComposedChart/03-hover-highlight": { hash: 'b6bbd19b', zh: "hover 某一列时，会把它以外的每一根柱子调暗。这个高亮读的是图表自己的 tooltip 索引，而那正是它出处那边缺掉的一半：状态是有的、离开时也会被清掉，但从来没有任何东西去设过它，于是这个高亮从来没有触发过。它由指针驱动，所以它永远不能是唯一承载某个结论的东西——可点击的图例、tooltip，以及这个图形隐藏的数据表，才是键盘够得到的那些。" },
  "ComposedChart/04-brush-and-loading": { hash: '535cf993', zh: "一张仪表盘图表大半时间都待着的两种状态，并排放着。左边是三十天之上的一个 brush：作为子元素组合进来，上面那张图随后只渲染它选中的那个窗口。右边是同一张图在加载——而即便你在那儿组合了一个 brush，它也不会出现，因为 isLoading 开着时 brush 会被抑制：此刻还没有东西可供你从中挑一个窗口。" },
  "Facet/01-default": { hash: '26d83590', zh: "六个渠道画成六张共用一个 domain 的小图，而这就是这个组件存在的全部理由。Social 的峰值是 410，Organic 是 6,400，而这个比例正是这张网格说出的第一件事——在各自独立的刻度上，两者会画出同样一条上升的线，于是读者此行要做的那个比较，不只是丢了，而是被颠倒了。这把共享的刻度是跨面板算出来的，并作为 panel.domain 交给渲染函数；一个不把它传给自己数值轴的面板，等于主动退回了那个坏掉的版本。yLabel 和 xLabel 是为整张网格印一次、而不是每个面板印一次，这就少了五个读者不必再读一遍的坐标轴标题。" },
  "Facet/02-overplotted-vs-faceted": { hash: 'a01fb0ee', zh: "同样六个渠道来两遍，而这个取舍被摆成了一幅画。上面是一张图、六条线：图例得被一路带回那团乱麻里去对，而 Paid search 腰斩这件事，藏在 Organic 的上升底下看不见。下面是六张共用一个 domain 的小图，那一次下跌是你看到的第二件事，而排名是第一件。分面的代价是失去了直接叠加——两条具名序列之间的交叉和缺口没了，而超过五条序列左右，这个代价每次都值得付——它还要求你重塑数据，因为一张多序列图表每个月吃一行、每个渠道占一列，而一张分面图是每个月每个渠道吃一行。" },
  "Facet/03-scale-and-overflow": { hash: '745a2c27', zh: "两张网格只差一个属性，然后是那个上限。右边每个面板都填满自己的盒子，于是从没越过 410 的 Social，画出和 Organic 那个 6,400 一样的爬升：这不是更难的比较，而是一个错误的比较，而且页面上没有任何东西承认这一点，这正是为什么 scales 用 independent 从来不是那个安全答案。下面是十四个渠道画成六个面板加一个 Other——sort 用 last 按各自的收尾位置排序，limit 在这张网格变成十四张邮票之前就把它封顶，而 overflow 用 fold 把长尾汇总进最后那个面板，好让合计仍然为真。无论哪种，这张网格都会在自己下面印一行，说明它略掉了什么，因为一张悄悄停在第六个的网格，是一张读者没法核查的网格。" },
  "FunnelChart/01-default": { hash: '58374620', zh: "默认的漏斗：四个阶段，最宽的在前，每个阶段的名字印在旁边。这个收窄编码的是相邻两个阶段之间的比值，而眼睛读的是被围住的面积，所以漏斗会夸大一次浅浅的下跌、压平一次陡峭的下跌——印出来的标签就是对此的补救，而当确切的流失率才是重点时，BarChart 会把每个阶段放到一把诚实的刻度上。顺序就是这个漏斗，而这里从不替你排序，所以最宽的那个阶段必须排在第一。" },
  "FunnelChart/02-variant": { hash: '6ba39add', zh: "stepped 是那个诚实的默认值：每个阶段保持同样的填充，光靠收窄来承载这次下跌。ramp 还会让每个阶段依次加深，那把同一个事实编码了两遍，并招来读者去比较两个其实是一个的东西——这个开关摆在这里是为了让这件事看得见，不是为了把两者当成对等的选项来提供。标签在每个阶段中心印的是人数、而不是阶段名，因为那个数字恰恰是收窄不值得被信任去传达的东西；阶段名由 tooltip 承载。" },
  "FunnelChart/03-stage-to-stage-rates": { hash: 'd0a95ffc', zh: "同一个漏斗上的两种标签：阶段名在里面，而它从上一个阶段留下来的占比在右边外面。收窄是一个眼睛读成面积的比值，所以它会夸大一次浅浅的下跌、压平一次陡峭的下跌，而印出来的比率是唯一能让流失变得确切的东西。这里最陡的一跌是从激活到付费，勉强三分之一撑了过去，而它恰恰是这个形状说得最少的一处，因为它发生在漏斗已经很窄的地方。每个比率都是相对它上一个阶段的占比，而不是相对最顶端，因为那是两个长得很像的不同数字，而一个不说清自己印的是哪一个的漏斗，会被读成对它更有利的那一个。" },
  "Histogram/01-default": { hash: 'e78aa143', zh: "一个分布的形状，而这正是箱线图从构造上就展示不了的：这 75 个样本里有两个峰——一条热缓存路径和一条冷的——而同样这些数字画出来是一个整整齐齐的箱子，对哪一个都只字未提。放任不管时，图表按 Freedman–Diaconis 分箱，即 2 倍 IQR 乘以 n 的负三分之一次方，它读的是四分位距而不是全距，所以一个远处的离群点没法把这幅画拉成一根高柱加四十个空槽。要像这里的描述那样，说清是哪条规则画出了这张直方图，因为这个形状既是数据的属性，也同样是分箱宽度的属性。" },
  "Histogram/02-bin-width": { hash: 'e089bf8b', zh: "同样这些数字，来四遍。bins 收的是等宽分箱的个数，而挪动它就是在挪动这幅画：五个的时候两个峰并成一个，四十个的时候形状消解成一排计数为一的柱子，而 auto 把这个选择交还给 Freedman–Diaconis。这不是一个该被调掉的缺陷——分箱本来就是这么回事——所以能守住的办法，是像标题那样说清是哪条规则画出了这幅画，以及在相信「两个峰之间那道空隙」这类特征之前，多看几个宽度。" },
  "Histogram/03-density": { hash: '0240511f', zh: "已经数好了才送来的分箱，宽度是某个指标后端挑的，而且随着数值增大越来越宽。在 frequency 下，100 到 250 那个分箱读起来像一个真实的肩部，而它之所以在那儿，只是因为那个分箱比第一个宽十五倍——一个更宽的分箱，在同样的底层发生率下会收进更多观测。density 把每个计数除以 n 乘以分箱宽度，于是这些柱子围出的面积为 1，那条尾巴也就塌回数据真正说的样子。只要分箱不等宽，就去拿它；只要两张样本量不同的直方图必须相互比较，也去拿它。" },
  "LineChart/01-default": { hash: '51fe0118', zh: "好几条序列相互比较，而这正是折线图存在所针对的那一个问题。这里刻意没有提供填充变体：把四条互相重叠的序列填上，那个比较就没法回答了。差别改由描边承载——第二条线是虚线，而不是把它丢给一档灰去分——而图例给两条都命了名，因为灰阶和虚线都不会自报家门。" },
  "LineChart/02-stroke-dot-curve": { hash: 'e634ed87', zh: "一条线上的三个旋钮：描边怎么画、每个点用什么标记，以及曲线怎么从一行走到下一行。每个圆点都是拿它所在的那个 x 处采样出的序列渐变上的色来涂的——一个填了那道渐变的满宽矩形，再裁成一个圆——因为直接去填那个圆，会让渐变在每个标记里重新开始，于是线上每个点都会涂成同一种颜色。curve 是那个会改变这张图所宣称的内容、而不只是它长相的旋钮，而那些行本身没法告诉你哪一档是诚实的。" },
  "LineChart/03-legend-variants": { hash: '777289b9', zh: "七种色块形状，而这个标记在这里干的活，比它在一套有彩色的系统里要多：两条线的差别是一档灰加一种虚线样式，而两者都不会自报家门，这正是为什么一条序列以上时图例是必需的、而不是装饰性的。让色块和标记对上——柱状图旁边配一根条、散点图旁边配一个点——常常是读者把图例和图连起来的最快方式。" },
  "LineChart/04-backgrounds": { hash: '59d19b74', zh: "十一块装饰性的底板，而这个数量正是重点：在没有色相可花的地方，一张图表的个性总得从某处来，而这块底板是唯一一个纹理可以放开手脚、又不跟标记打架的地方。它是画在绘图矩形上的、不是画在整张 SVG 上，所以数据到哪儿它就停在哪儿，绝不会跑到刻度标签底下去。不过它不是网格——这个例子是把它组合进来顶替网格的，而一块底板帮不了任何人从坐标轴上读出一个值。" },
  "LineChart/05-emphasis": { hash: '696941c1', zh: "把一条线从另一条里标出来的两种方式。一张单色图表没有更亮的颜色可以去拿，所以 glowing 在那条作为这张图重点的序列背后放一圈光晕，而它是这个包里唯一一处模糊。buffer 把最后那一段画成虚线，那是「这是一个预测、而不是一次测量」的惯用画法。showTitle 会把每个图形的名字印出来，默认藏起来，因为大多数调用处在图表上方本来就已经有一个标题了。" },
  "LineChart/06-brush": { hash: 'b2020e0f', zh: "四十行、两条序列，而这正是折线图开始自己跟自己交叉的地方。下面那条带子是整条序列的缩微版，上面罩着一扇被点亮的窗，对应上面那张图正在显示的那一段，于是读者在挑的过程中就能看见自己是从什么里面挑。它的手柄是用内联样式定位的，而不是靠 start 和 end 这两个类，这是刻意的：一张笛卡尔图在任何书写方向下都是第一行画在最前面，所以在 dir=\"rtl\" 下把它们镜像过去，会把靠前的那个手柄放到一张仍然朝另一个方向走的图表的末端。" },
  "LineChart/07-loading": { hash: 'f0aa2411', zh: "一页上每张图表在首次绘制时所处的状态。isLoading 把标记换成一份骨架，并保住图表量出来的高度，所以数据行落下来时页面上没有任何东西动。骨架的各行是在微光离开绘图区时重新掷出来的，而不是按定时器，因为一个 interval 会和动画错开相位，最终会在众目睽睽之下重掷，那读起来像图表在抽风，而不像它在加载。" },
  "LineChart/08-axis-labels-and-format": { hash: 'c792e37f', zh: "给一根轴所度量的东西命名，并且按读者心里的方式写它的数字。一根读作 0、100、200 的轴，完全没说这些是人数、毫秒还是美元，所以把单位命名一次——在轴上，或者在序列标签里，但只一次，因为第二份副本是噪音。formatNumber 返回的是一个函数而不是一个字符串，好让它能直接交给 tickFormatter，而 Recharts 每个刻度会调用它一次，它绝不能每次都重建一个 Intl.NumberFormat；格式化过的刻度也更宽，那正是那个显式 width 存在的原因。" },
  "LineChart/09-sonify": { hash: 'e3dcc6d3', zh: "两条序列一前一后播放，各自先报出名字，而不是同时播放、一条向左耳一条向右耳。声像是更好的演示、更糟的选择：它假定有立体声输出和两只能用的耳朵，所以一个单声道扬声器或者一只助听器，会把两次播放塌成一段听者拆不开的旋律，而且它把这个特性的上限锁死在两条序列。两条都是对着同一个范围定音高的，正如它们在屏幕上共用一根数值轴，所以 p50 在范围低处的平坦是作为平坦被听见的，而不是被重新归一化成第二条跌宕起伏的线。" },
  "LineChart/10-toolbar": { hash: '5ba4d85d', zh: "工具栏和 brush 驱动的是同一扇窗，所以它们不可能各说各话：用按钮走一步缩放，下面的手柄会动；拖一下手柄，重置缩放会亮起来。九十天正是那种两个都想要的场景——带子显示你在从什么里面挑，按钮则精确地一步步走进去。组合这个工具栏，同时也会打开绘图区自己的手势：它变得可聚焦，方向键平移，加号和减号缩放，零重置，而横着拖过绘图区会缩放到那一段。滚轮被挡在 Ctrl 或 Cmd 后面，因为一张吞掉普通滚轮事件的图表，会把页面的滚动困在指针底下。" },
  "PieChart/01-default": { hash: '2c4ba8f1', zh: "默认的组合方式——扇区、一块 hover 面板和一份图例。饼图是靠角度来读的，而那是所有可选编码里最不精确的一种，所以它回答的是「大概占多少」，再精确就没有了：用眼睛把 275 和 200 排出名次是不可靠的，而超过五个扇区——恰好就是这么多——BarChart 能把同一个问题答得更好。图例在这里不是装饰，因为饼图没有分类轴，也没有别的东西为这些扇区命名；这个图形还附带一张同样行的隐藏表格，而确切的数字就住在那儿。" },
  "PieChart/02-shape": { hash: 'ddb066b7', zh: "三个属性——innerRadius、paddingAngle 和 cornerRadius——在同一组四个值上做出四种形状。把 innerRadius 抬到零以上就得到一个环形图，而它是两者里更好读的那个：那个洞拿走了读者本来会去判断的面积，只留下弧。最后一个选项设了一个负的 paddingAngle，让扇区互相重叠，而每个扇区随之带上的那圈表面色描边，正是把它们重新分成一叠卡片的东西——那是一种长相、不是一种读法，因为这四种形状画的是同样四个数字。" },
  "PieChart/03-labels-and-emphasis": { hash: '458adcdd', zh: "针对同一个弱点的两种回答，并排放着。左边，PieChart.Label 把值印在每个扇区上：饼图全部的弱点就在于角度难读，而一个印出来的数字把猜测彻底拿掉了。右边的问题不是排名、而是某一个扇区——glowingSectors 给 Chrome 加了光晕，而在饼图和图例上都开着的 isClickable，让一次点击把其余每个扇区降到 15% 不透明度，于是被选中的那个独自站着。数字要紧时去拿标签，只有其中一个要紧时去拿光晕。" },
  "PieChart/04-loading": { hash: 'c36639f8', zh: "骨架。isLoading 把标记换成五个等分的扇区，并保住这个图形量出来的高度，所以真实数据落下来时页面不跳。它们是错峰脉动的，正是这一点让那道波绕着饼走，而不是整个饼一起眨眼；在 prefers-reduced-motion 下，它们改为停在一个平的中等不透明度上。你会为有数据时组合的那些部件，在这里照样组合——innerRadius 在这个状态下也会被读取，所以加载中的环形图和取代它的那个是同一个形状。" },
  "RadarChart/01-default": { hash: '1f770b62', zh: "一份画像，横跨六个具名维度：雷达图提供的是一个可供辨认的轮廓，而不是可供比较的量级。有两个后果直接来自几何、而且都不是口味问题——把每个值都翻一倍，多边形围出的面积会变成四倍，所以那层填充夸大了它看起来所展示的差别；而重排那些辐条，会把同样六个数字画成另一个形状，这让轴的顺序成了一个图表自己没法标注出来的选择。dot 用 border 变体标出每个顶点，而值真正所在的正是那些顶点；它们之间的边是插值，不是数据。" },
  "RadarChart/02-variant-and-grid": { hash: 'f51d29d9', zh: "网上多出第二条序列，以及决定这一对能不能被分开的那两个属性。填充的多边形会重叠，而透过两层半透明去判断面积，恰恰是雷达图最不擅长的一件事——lines 放弃填充、保住轮廓，而形状本来就是靠轮廓承载的。gridType 用 circle 把多边形的网换成同心圆，于是网格读起来是一把刻度，而不是作为第二个形状去跟标记打架。点击一条序列或它的图例条目，会把另一条降到五分之一的不透明度，而那正是回到「一次只看一个轮廓」的路。" },
  "RadarChart/03-loading": { hash: '3801609f', zh: "骨架。雷达图没有一根笔直的轴供一道行进的高光跑过去，所以它的动画是在形状之间变形——六根辐条每 1.5 秒重掷一次，由 Recharts 自己的过渡来承载这次变化；在 prefers-reduced-motion 下动画关闭，形状就那么停着。辐条的值来自一个确定性函数、而不是 Math.random，因为一份和客户端对不上的服务端渲染骨架，就是一次水合不匹配。isLoading 设着的时候，把那些部件继续组合在那儿：网格照样画出来，Radar 本身什么都不渲染，而数据到达时两者都会以本来面目回来。" },
  "RadialChart/01-default": { hash: '4307750a', zh: "三个合计画在一段弧上，没有 max，所以刻度来自数据，最大的那根条永远填满整个环。要当心的地方是几何性的：一根条的长度是它的值，但它的半径不是，所以内圈一根条和外圈一根条握着同一个数字，画出来的长度不一样，而这个环偏袒的永远是待在最外圈的那个。这让它成为一个给三四个「读者只会瞟一眼」的值用的展示，而任何要排名次的东西，诚实的选择是 BarChart。命名的活由图例来干，因为这些弧自己不带坐标轴。" },
  "RadialChart/02-gauge": { hash: '58e41a55', zh: "一个值对着一个固定的总量——这是径向图毫无争议地正确的那个场景。max 才是让它成为仪表的东西：没有它，刻度来自数据，孤零零那根条永远填满整段弧，于是 62 和 98 会被画得一模一样。条形背后那条轨道是这次读数的另一半，因为它正是这个值所占其中一份的那个余量。semi 把圆心降到盒子的 70% 处，好让这个半圆坐在自己那块空间的中间，而不是顶部。" },
  "RadialChart/03-loading": { hash: '63102baa', zh: "骨架。isLoading 把这些弧换成五段它们自己的弧，每 1.5 秒重掷一次并在长度之间变形，同时保住这个图形量出来的高度，所以数据落下来时页面不跳；在 prefers-reduced-motion 下它们改为停着不动。那些长度来自一个确定性函数、而不是 Math.random，所以服务端和客户端画出同一份骨架，水合也就没有什么可以对不上的。组合进来的 RadialBar 在这个状态下什么都不画——它在这儿，是为了让数据行到达之后，这张图能以本来面目、带着同一根条回来。" },
  "SankeyChart/01-default": { hash: '079782d2', zh: "这里唯一一张数据是图而不是表的图表：它收的是节点和连边，而每条连边用在节点数组里的下标来指认它的两端。宽度就是量，而一个节点画多高，取决于流经它的量，所以数据里漏掉的一条连边，会悄悄把它本该喂养的那个节点缩小——而一条回流到它已经离开过的阶段的流，根本没有从左到右的读法。隐藏表格列的是流、而不是节点，理由相同：一张节点合计的表格，会把这张图存在所要陈述的每一组「从哪到哪」全部丢掉。NodeLabel 配 showValues 会把数字印在每个名字旁边，因为一条带子的宽度，用眼睛量起来并不比一个扇区的角度更容易。" },
  "SankeyChart/02-links-and-labels": { hash: 'cb1afdf9', zh: "同一张图上的四种连边变体和两种标签位置。gradient 把源端的颜色淡入到目标端的颜色，是那个读起来像流动的选项；source 和 target 把整条带子归属给某一端，而当问题是「这是从哪来的」而不是「它后来变成了什么」时，就去拿它；solid 完全放弃颜色，让节点矩形去承载身份。标签设成 inside 时，需要一个宽到装得下它的节点，这也是为什么那个开关会把 nodeWidth 从 12 一下抬到 76——留在 12 上，标签会跑到它本该待在里面的那个形状之外。" },
  "SankeyChart/03-loading": { hash: '5ebe6159', zh: "骨架，也是这一组里唯一一个无视自己数据的：isLoading 设着的时候，这张图会被换成一张固定的八节点、十一连边的图，于是在任何东西到达之前，这个形状读起来就已经是一张桑基图，而 data 属性只需要满足类型即可。节点和连边是错相脉动的、不是一起，正是这一点让一份骨架不至于读起来像一整块在眨眼；在 prefers-reduced-motion 下，它们改为停在固定的不透明度上。Node 和 Link 是根节点会读取的插槽，所以在这里组合它们不花任何代价，而这也正是图数据落下来时这张图能以本来面目回来的原因。" },
  "ScatterChart/01-default": { hash: '5ae5a862', zh: "两个度量互相对着放，一个观测一个标记——这是这里唯一一张 x 轴是数字、而不是分类的图表，正是这一点让它能回答相关性、聚集和离群点。七个点一起往上走是一个图形，不是一个系数：这里没有任何东西在拟合一条线，这张图也没有宣称 ms 里有多少份额是由 kB 解释的。每个实心标记都带着一圈表面色的环，那道细线让两个重叠的观测仍然数得清——超过几百个点它就不管用了，密度得换别的方式来展示。table 属性不是记账：散点图的数据行住在每一个 Scatter 上、而不是根节点上，所以和这个包里其他每一张图表不同，那张隐藏表格推断不出来，必须显式声明。" },
  "ScatterChart/02-shape-and-variant": { hash: 'ac5d721c', zh: "两片互相重叠的点云，以及把它们分开的那些属性。这个包的灰阶是单色的，所以 shape 干的是别处由色相干的活：圆形对十字，把两片重叠的点云分开的效果，远好过两档灰，而且一个形状在叠印之下还活着，一档明度差则不然。outline 把标记挖空，而当点云互相压在一起时，就该去拿这个版本，因为一个空心标记能露出它底下的那个。超过三条序列，形状就不再能把它们分开，而答案是一张小倍数网格——一条序列一张图、同样的坐标轴——不是第四个字形。" },
  "ScatterChart/03-bubbles": { hash: '4b85e7e5', zh: "同样两根轴上的第三个度量，由 ZAxis 承载。Recharts 是按面积单位来缩放 z 范围的，正是这一点让它安全：改成把值映射到半径，翻一倍墨水就变成四倍，于是一次下载量翻倍的发布，读起来会像受欢迎程度翻了四倍。这里 60 到 900 的范围，是十五倍的面积跨度，大约四倍的直径跨度。outline 也是刻意的——气泡在构造上就会重叠，而一个实心标记会把它压住的那个更小的气泡藏起来。" },
  "TreemapChart/01-default": { hash: 'fa3309ab', zh: "八个包，作为一个整体的一次划分。矩形树图把值编码成面积，而眼睛读面积比读长度差、比读角度好得多，它也是这里唯一一种到五十项还保持可读的形式。有两条规则让它保持诚实：不能有负值，因为面积不能是负的；以及这些方块必须加总成一个读者认得出是「整体」的东西——十来项以内、又要读排名的时候，BarChart 是更精确的编码，因为矩形树图刻意不只按值来排列它的方块。" },
  "TreemapChart/02-nested": { hash: '0935e06c', zh: "两层，以及给它们上色的两种方式。ramp 沿着序列的灰阶走，于是同级之间靠明度分开，而这正是一组扁平方块想要的；nested 则改为按深度加深，于是同一层上的每个方块共享一个分量，而颜色所回答的问题变成了「什么装在什么里面」。只有叶子带尺寸——一个枝干是它子节点的和——而那张隐藏数据表被压平到这些叶子上，因为一棵嵌套的树一行一行念出来，没有谁跟得下去。" },
  "TreemapChart/03-many-small-tiles": { hash: '3be5c9f3', zh: "长尾，而这既是矩形树图挣得它一席之地的地方，也是它不再为自己命名的地方：一个方块只有在宽于 56 像素、高于 26 像素时才会被打上标签，所以承载这条路由的那两个文件有名字，而其余十八个里的大多数是匿名矩形。tooltip 在指针底下一次命名一个，而那张隐藏数据表——从画出这些方块的同一批叶子生成，所以两者不可能对不上——正是让那些小方块不靠指针也够得着的东西。dataKey 是面积据以度量的那个叶子字段，也是那张表所印出的那一列。" },
  "WaterfallChart/01-default": { hash: '1580184a', zh: "一个期初合计、四笔带正负号的贡献，以及一根本身不带值的收尾柱：它就是那些变动加起来的结果，所以它永远不可能和它上面那些步骤对不上。减少取 45 度斜纹，增加取实心填充——用纹理而不是第二种颜色，于是这个读法在灰度和强制色彩下都还活着——而一个合计是靠几何和一次增加区分开的，因为它是唯一一种站在基线上的柱子。这里的各步是同时发生的，它们的顺序是一次编辑取舍，而描述里把这件事说了出来：算术怎么排都成立，但那些连接线画的是一个序列，而读者一定会把最左边那根柱子当成第一个原因。" },
  "WaterfallChart/02-subtotals": { hash: 'd4609e01', zh: "type 用 total 会在基线上立一根柱子并重设累计值，而这里在中间用了两次——毛利，然后营业利润——于是这条瀑布在读者本来要在脑子里加五段悬空长度的地方，把自己重述了一遍。两个小计都不带值，所以两个都不可能和它们上面那些步骤对不上。把连接线关掉，同样这些柱子就成了一排高度毫不相干的长度，而这既是把它们留着的理由，也是把它们刻意去掉的理由：当各步的顺序是随手排的，那些连接线宣称的是一个数据本身并不具有的序列。" },
  "WaterfallChart/03-against-a-plan": { hash: 'dd84dd0c', zh: "那根收尾柱说出总量落在了哪里；它没说那是不是计划所说的地方。一条参考线把那一个数字横着画过整条瀑布，画在柱子之上而不是背后——一个被柱子盖住的目标是一个没人核查得了的目标——而且它会把坐标轴撑开去容纳自己，而不是被丢掉，这正是它在这里看得见的原因，因为这个计划值高于图中每一根柱子。weight 用 firm 是实心墨色，留给那一条图表真正在讲的阈值；安静的默认值是一条虚线细线，留给那些必须在场、又必须明显不是数据的背景。" },

  // ─── Diagrams ───
  "ArchitectureFigure/01-default": { hash: '229c98f9', zh: "一条请求路径，画在默认栅格上：每个组件都指名了自己的行和列，所以这里没有任何东西是被算出来的，服务端发出的标记就是浏览器留下的标记。区域边界正是让 ap-southeast-2 成为一个地方、而不是第六个盒子的东西，也正是它把浏览器明确地放在了外面。有一条连接带着强调——没有它，四条等分量的箭头会让读者自己去琢磨这张图到底在讲哪一条。" },
  "ArchitectureFigure/02-two-kinds-of-boundary": { hash: 'b61f2319', zh: "两种边界，一种嵌在另一种里面。region 是围在「某样东西运行的地方」外面的实线框，而 security-group 是围在「什么可以够到它」外面的虚线框，所以一个带着这两个问题之一而来的读者，不用读任何一条说明文字，就分得出哪个框回答的是他的问题。security 那个变体标出了唯一那一跳跨过虚线的连接，而它里面从队列到 worker 的箭头完全没有配文字——只有当恰好只有一条箭头离开那个盒子时这才负担得起，一旦有第二条，它就成了猜测。" },
  "ArchitectureFigure/03-a-denser-map": { hash: '726cf1c8', zh: "八个盒子、八条线，画在一张通过布局收紧过的栅格上，而这既是一个真实系统的样子，也是密度的代价：到了这个数量，没人会去追一条路径，他们是在扫着找一条。那两条被强调的连接和下面那些卡片就是补救——更重的那一段说明从哪儿看起，而那些卡片把结论直接陈述出来，好让读者不必自己去推。一张这个尺寸、每条线都一个分量的图，是一堵在邀请读者去解题的墙。" },
  "ArchitectureFigure/04-placed-by-hand": { hash: '0a7ec569', zh: "用 pos 而不是 row 和 col，而这正是解锁一条手工调过的走线的东西：via、channelX 和 channelY 只有在这条连接的两端都是绝对定位时才会被采纳。在两个栅格组件之间，它们是渲染器自己选的坐标系里的坐标、而不是作者选的，所以它们会被丢掉，线路一声不吭地重新布置。这里也没有任何东西检测碰撞——两个被给了同一个坐标的组件，会一块板压着另一块板画出来，图形照样渲染，而旁边那份摘要列表仍然把两个都报出来。" },
  "DataflowFigure/01-default": { hash: '76297011', zh: "两个来源汇入同一道闸口。每个标签底下那枚等宽字芯片是分级，之所以和文案分开印，是因为一条流水线被读的是箭头里面装着什么，而不是这条箭头叫什么——clickstream 和「无 PII」回答的是不同的问题，而其中只有一个是合规审查者此行带来的那个问题。阶段标题就是那根轴，所以「某样东西走到哪一步了」是靠往上看回答的，不是靠追踪。" },
  "DataflowFigure/02-one-source-three-consumers": { hash: 'cb1a0666', zh: "一次扇出，以及分级之所以是一个字段、而不是标签里一个词的理由：一张表喂给三个消费方，而每条箭头离开时携带的东西都不一样。这里三条流共用一个面，所以路由器把它们的端口摊开在这个面上——若是全叠在这个面的中点上，三个箭头会被读成一个。广告合作方是唯一一个在账户之外的消费方，这也是为什么它那条流是被画成跨越边界的那一条。" },
  "DataflowFigure/03-a-stage-the-data-skips": { hash: '8cfac709', zh: "一个阶段是关于「某样东西走到哪一步」的断言，而正是这根轴让这次绕行变得看得见：那份采样副本在阶段零离开 SDK，到达阶段二，中途没有经过脱敏器，仍然带着它的 PII 芯片。同样这三条流，写成一份成对的列表就会把这件事藏起来，因为一份列表没有轴可供跳过。被强调的那条线是这条流水线存在的目的；那条虚线是留了一份百分之一的采样，好让某个人能去调试一段载荷，而那恰恰是一次审计最后才发现的那类路径。" },
  "DataflowFigure/04-what-is-in-the-arrow": { hash: '44ea9d26', zh: "四个阶段，因为最小化本身就是一个阶段：审查者的问题是「还标着 PII 的东西有没有到达数仓」，而答案是一条你可以顺着走下去的线，不是一段你只能选择相信的话。每一个分级除了印在芯片上，也一并折进无障碍摘要里，所以一个看不见这幅画的读者拿到的是「卡号和邮箱 — PII」，而不是光秃秃的「卡号和邮箱」。哪怕文案和分级感觉像是一句话，也要把它们分开；两者一旦合并，芯片就不再是一个可供任何东西去核对的字段了。" },
  "DiagramCanvas/01-default": { hash: '5a7a4e2f', zh: "一张比给它的地方更宽的图形，装在一个可以围着它移动的框里。拖动是平移，角落那块板负责缩放，而它两个按钮之间那个百分比是重置；普通滚轮刻意留给页面，所以只有 Command 或 Control 加滚轮才缩放。这个框是一个真的 tab 停靠点，所以加号、减号、零和方向键完全不用指针也能干同样的活。这个图形自己的标题、图例和卡片在这里被关掉了，因为这块画布装的是画，不是一篇文章。" },
  "DiagramCanvas/02-your-own-controls": { hash: '2a5cd4d0', zh: "controls={false} 会拿掉角落那块板，而它原本做的一切都得在别处补回来：zoomIn、zoomOut 和 reset 挂在那个 handle 上，而 ref 是够到它们的唯一途径。当页面本身已经有一条工具栏、两套缩放按钮会为同一份活打架时，就把内置控件关掉。关掉之后又什么都不提供，缩放就只剩下修饰键加滚轮和键盘，而这两样读者都没有任何办法发现。" },
  "DiagramCanvas/03-following-the-view": { hash: '4bc4b594', zh: "onViewChange 会在每一次平移、缩放和重置时触发，带着画布正在用来做变换的那同样三个数，而一个百分比读数、一张缩略图，或者一条深入图内的链接，都是拿它搭出来的。centerOn 是反方向的，它收的是画作自身坐标空间里的一个点，不是一个节点 id——画布是一个视口，对节点一无所知，所以一个想跳到某个节点的调用方，必须自己知道它被画在哪儿。" },
  "DiagramExportMenu/01-default": { hash: '6c59dc0e', zh: "一个触发器后面五个文件，按用途分组：PNG、JPEG 和 WebP 是按 2 倍栅格化的画作，SVG 是画作本身、每一个自定义属性都解析成了真实颜色，而分享卡是一张 1200 × 630 的 PNG，标题印在图的上方。targetRef 指向的是图形外面那层容器、不是那个 svg，菜单会在它里面找到图形自己的画作。title 是给下载文件命名的东西，会被 slug 化——「Request path」到手就是 request-path.png。" },
  "DiagramExportMenu/02-what-lands-in-the-file": { hash: '64a59430', zh: "这里的 ref 把工具栏也一并裹了进来，而那条工具栏里的每个图标本身都是一个 svg——菜单会先去找图形自己的画作标记，正是这一点让一次「导出这张图」不至于变成一张信息按钮的照片。离开页面的只有画作本身：工具栏、面板，以及任何其他用 HTML 画出来的东西都不在文件里。颜色是从活的元素上读的，所以下载下来的是读者此刻正在看的那个主题；但网页字体不会跟着走，一台没有这个字族的机器会用别的字体来排那些标签。" },
  "DiagramExportMenu/03-your-own-pipeline": { hash: 'acab587e', zh: "onExport 把整份活接管过去：序列化、栅格化和下载这几步一概不跑，所以除非这个处理器自己去写，否则不会有任何东西被写到磁盘上。当文件必须来自浏览器去不了的地方时就去拿它——一个服务端渲染器、一个你自己定的画幅尺寸、一个队列。onResult 无论哪种情况都照样触发，也正是页面用来弹一条提示的那道接缝；trigger 替换的是按钮、不是菜单，所以一个只有图标的触发器仍然需要它的 aria-label。" },
  "DiagramInspector/01-default": { hash: '8e0a098b', zh: "一次选择会往屏幕上放的东西：它是哪一类东西、它的名字、那些长到印不进板子里的事实，以及它参与的每一条关系，方向都写明白。它是一个带 aria-live 的具名区域，不是一个对话框——读者点的是一个节点，不是打开了一块面板，所以这里没有任何东西劫持焦点，也没有什么必须先关掉页面才重新能用。mono 是给读者可能会重新敲一遍的值用的；那些事实是一份定义列表，所以读屏软件能说清哪个值属于哪个标签。" },
  "DiagramInspector/02-nothing-selected": { hash: '919baf9a', zh: "这块面板自己没有空状态——title 是必填的，所以根本没法渲染一个里面什么都没有的它，而读者在挑中任何东西之前看到的是什么，归调用方去画。一定要画点什么：一根在选择被清空时就消失的列，每次有人关掉面板都会把布局的其余部分一起带走。关系那一行是一个真的按钮，因为它带着 onSelect，而正是这一点让键盘可以一个邻居一个邻居地走完整张图，全程不碰那幅画；onClose 回到那个空的情形。" },
  "DiagramInspector/03-pinned-over-the-figure": { hash: '37f8320d', zh: "floating 会把这块面板变成一块钉在最近的定位祖先左下角的板，所以那层容器必须自己建立一个定位上下文，否则它会把自己钉到页面更上方的某个东西上。当图形占据整个视口、而排在文档流下面的面板在最需要它的那一刻却在屏幕之外时，就把它钉住；当图形只是一篇文章里的一项时，就让它留在文档流里。activeIds 会点亮这块面板正在讲的那个节点，而两者谁也不伸手去够对方——画面和面板是同一份选择的两个消费方。actions 是「读者拿这次选择去做什么」的去处。这个区域的无障碍名称取自 title，所以一页上的两块面板绝不能检查同一个节点——这一块选的是那个数据存储，而不是第一个例子所讲的那个服务。" },
  "DiagramLegend/01-default": { hash: '6ee82a85', zh: "渲染器为自己构建的那几套里的两套。kindLegend 用板子画符号时所用的同一个组件来画每一个符号，并且用板子引题所印的同一个词来给它打标签，于是图例和它上面那张图不可能各走各的；stateLegend 则把每个状态画成板子本身，连颜色和虚线一起。title 默认是「Key」，这也是为什么第二个被改了名——两个图例摞成一列、都顶着「Key」，等于对「哪个是哪个」只字未提。" },
  "DiagramLegend/02-lines-rather-than-plates": { hash: '1a46c631', zh: "variantLegend 给关系、而不是给盒子编制图例，把每一条目画成那道笔画本身——一条主路径更重的分量、一条跨越信任边界的线那种长虚线、一条不阻断的线那种短虚线。像这样的图例里，把 return 那个变体留在外面：它画出来和 dashed 一模一样，在图中是靠一个空心箭头分辨的，而一个 14 × 14 的样本没有地方展示那个，所以把两个都列上，等于给读者两个名字不同、样子完全相同的记号。第二行覆盖了一个标签，并把 title 传成 null 以得到一行光秃秃的图例，因为它上面那个图例已经说过「Key」了。" },
  "DiagramLegend/03-a-key-you-draw-yourself": { hash: '48dc6f5f', zh: "sample 收的是画在 14 × 14 栅格上的标记，而不是一个拿去和固定清单比对的名字，正是这一点让一张自己画了某种记号的图，能够为它写说明——这里是三种没有任何渲染器知道的归属状态。放进去的东西必须就是画作画出来的那个记号：一个自创形状的图例，会让读者在画里到处去找一个从来不存在的东西。用图相关的 token 去画这些样本、别用固定颜色，好让图例跟着图形一起进暗色模式、一起上纸。" },
  "DiagramMinimap/01-default": { hash: '752b957e', zh: "只有当框比画作更小时，一张地图才值得画出来，所以 frame 承载的是画布自己以 CSS 像素计的盒子，content 承载的是图形的自然尺寸。那个矩形是每次变化时从画布的 view 推导出来的、不是另存的，这正是为什么两者永远不会对不上。在地图上点击或拖动会报出画作坐标系里的一个点，而移动的动作由 centerOn 来做——缩略图对视图没有权柄，它只说读者指了哪儿。" },
  "DiagramMinimap/02-what-the-rectangle-is": { hash: 'b98e4a51', zh: "同一张地图的三份，除了 view 之外别无差异。那个矩形是拿那三个数算出来的——框左上角对应的内容点，是取负的偏移量除以缩放比，再换算到地图上——所以「视口在哪」没有第二份副本，也就没有什么需要同步。放大会让这个矩形变小、而不是移动，而这正是读者想要的那个读法：它说明的是他们此刻看到的是整体的多大一部分。这三个都没有传 onSeek，所以它们是读数而不是控件，指针也保持它平常的光标。" },
  "DiagramMinimap/03-when-a-minimap-earns-its-place": { hash: '63509105', zh: "两种情形并排放着。左边，框是一扇窗，望着一个四倍于它面积的东西，所以那个矩形圈出了一部分，地图回答了「你在哪」；右边，框已经装下了整幅画作，矩形从边到边盖满了地图，而它的每一个像素说的都是读者本来就已经看见的那一件事。只在第一种情形下渲染缩略图——在第二种情形下，它是这张图的第二份绘制，花掉一次渲染，却什么也没告诉任何人。" },
  "DiagramToolbar/01-default": { hash: '01b06657', zh: "两组共四个控件，用一条细线分开、而不是用空白——一道宽到读起来像边界的空隙，同时也宽到让这条栏不再读起来像一个整体，而把这些控件收进一条栏里，本来就是唯一的理由。外层容器带着 role=\"toolbar\"，这也是为什么 label 是必填的：没有它，读屏软件会播报出一个没有名字的工具栏。这里没有实现漫游焦点，所以 Tab 会依次走过四个按钮；当这不对时，就换成一个普通的 div、把这个 role 去掉。" },
  "DiagramToolbar/02-floating-over-a-canvas": { hash: '6d3453e5', zh: "placement=\"floating\" 把这条栏钉在它所作用的那片表面之上，而 align 挑的是哪个上角。它必须是画布在一个定位容器里的兄弟节点，不是它的子节点：任何作为 children 传给 DiagramCanvas 的东西都会进到那个被变换的舞台里面，所以一条交给它的工具栏，会跟着它本该控制的那张图一起缩放和平移。而导出菜单取 ref 的正是同一层容器，于是这幅画和那个保存它的按钮是同一个对象。" },
  "DiagramToolbar/03-a-different-set-of-controls": { hash: 'ff72727b', zh: "同一条栏，装着的控件改变的是这张图说什么、而不是它被怎么看——一次引导式阅读，一次一章。当前这一章除了用 secondary 变体标出来，还带着 aria-pressed，因为变体是颜料上的差别，而读屏软件看不见颜料。第二组装的是一个读数、不是一个控件：group 就是一个普通的 div，而那条细线正是说明这个计数属于这条栏、而不是跟在它后面拖着的东西。" },
  "LifecycleFigure/01-default": { hash: 'ae960dd5', zh: "顶上那根轨并不在 spec 里。一张生命周期图会把第一条泳道让给那些有序的阶段，而那里相邻两列之间的箭头会按强调分量替你画好，所以作者只需声明那些离开主干的边——这里就是穿过 Blocked 的那三条。这也是唯一一张被允许用颜色的图，而它恰好花掉两个 token：一个给完成状态，一个给失败状态。其余每一类都由形状承载，所以一次灰度打印丢掉的是那两个结局，其他每一处区分都还在。" },
  "LifecycleFigure/02-a-decision-with-both-ends": { hash: '63f3cbd2', zh: "一个决策，两个末端都画了出来。Approved 坐在轨上，所以它那条箭头是隐含的；Declined 坐在第二条泳道里，而这是在这里从一个决策扇出的唯一方式——往第一条泳道里再加第四个状态，它会被那条隐含的轨和邻居连上，无论这个转移是否真的存在。那两个终态是这个包里仅有的被允许用颜色的记号，而这张图正是那两个 token 被预留下来所针对的：读者带到一台状态机跟前的问题，是「这一趟是从哪个末端出来的」。" },
  "LifecycleFigure/03-a-failure-with-a-way-back": { hash: 'fa121cb7', zh: "两个 failure 类型的状态，画得一模一样，而其中只有一个会终结这一趟。板子上没有任何东西说明一次失败是不是终态——差别是机器里一条真实的边，所以 Timed out 有一条回到 Sending 的箭头，Rejected 没有，而读者是靠追箭头、不是靠读一个形容词来分辨它们的。那条重试边在它的文案下面带着一条注记，而当把某个计数或条件折进标签里会让标签长到塞不进那道空隙时，它就该去那儿。" },
  "LifecycleFigure/04-the-implicit-rail": { hash: '729d2247', zh: "三个关于摆放的事实，每个都只会咬你一次。声明主干上本来就有的一对，不是重复——它会替换掉那条隐含的边，并采用你的标签——所以给某一步命名的办法是把那个转移写出来，而不是指望那根轨替你带上。第二条泳道的第 N 列，坐在主泳道第 N + 2 列的下面，这也是为什么位于第 0 列的 Withdrawn 落在 Accept 底下、而不是 In review 底下。还有，yOffset 在一个状态上是被接受、然后刻意被忽略的：那点微调是按 archify 的泳道深度来量的、不是这里的，所以照做会把一块板子掉到下面那条泳道里。" },
  "SequenceFigure/01-default": { hash: 'f1a9ed6a', zh: "一次缓存未命中，顺着页面往下读，而竖轴是时间、不是布局：未命中和查询之间那 50 个单位是一段真实的间隔，而一份六次调用等距排开的列表，会把它抹掉，同时看起来还更整齐。那些激活条承载的是一份调用列表承载不了的事实——在 API 保持打开的那 210 个单位里，Redis 忙了 45 个单位。返回用虚线、配空心箭头，两个信号而不是一个，因为在一条密集的调用轨迹里，读者最先挑出来的就是回复。" },
  "SequenceFigure/02-an-asynchronous-hop": { hash: 'a4dec021', zh: "一次投递中异步的那一半。入队是虚线，因为 Billing 不等它——Billing 压根没有激活条，而正是这一点说明随后那两次尝试对调用方不花任何代价。两次对外调用都带着 security 变体，图例把它读作跨越信任边界，而在这里这是真的：那个端点属于客户。column_fit 用的是 spread，因为「Partner webhook endpoint」装不进固定的 148 单位列宽，而为了塞得下去把名字缩短，那会是另一张图了。" },
  "SequenceFigure/03-time-as-the-axis": { hash: 'dc9f241c', zh: "一个显式的 y 买到了什么。前三次调用相隔 12 个单位，因为它们是一起离开网关的；而供应商的回复在它那次调用下方 186 个单位处，因为它就是花了这么久——换成按下标摆放，这六条消息会等距排开，那个差别也就没了。那些激活条用第二种方式承载同一个事实：两条早早收尾，而第三条一路跑到图的底部，那就是长尾，在任何人读到一个标签之前就已经看见了。" },
  "SequenceFigure/04-names-that-do-not-fit": { hash: '6121f6e9', zh: "column_fit 用 spread，它会把每一列都撑到最宽的那个参与者名字，而不是守着那个固定值。只要一个真实的名字会被裁掉，就立刻去拿它：板子会折成两行、其余部分打省略号，而为了塞得下去把名字缩短不是一种修复——名字就是数据，dealer-portal-api 和 api 是两个不同的服务。一条点名了 participants 里没有声明的参与者的消息，根本不会被画出来，因为没有列可以让它画在中间；它会以原始 id 的形式留在摘要列表里，于是文字报出了一次画面没有展示的调用。" },
  "WorkflowFigure/01-default": { hash: '87f0cb20', zh: "一条发布流水线，失败路径单独占一条泳道。mainPath 才是给这张图一个主语的东西：它上面任意两个相邻 id 之间的每一条边，无论自身的 variant 是什么，都会按强调分量绘制，于是一个顺着那条重线走下去的读者，一个字都不用读就拿到了正常路径。异常泳道是这些图里唯一那条打了淡色底的带子，而那条回滚边是刻意画成虚线且弱化的——一条按正常路径的分量画出来的失败路径，是一份没人能扫读的操作手册。" },
  "WorkflowFigure/02-a-branch-and-both-outcomes": { hash: 'afd6d70b', zh: "一次检查，两个结果，而一个工作流的大部分就是这个形状。穿过 Checks 到 Merge 的那条重线是 mainPath，而从它岔出去的那条分支是虚线——但图例默认把虚线命名为 Asynchronous，所以这份 spec 把那个条目改了名，而不是任由图例和画面互相矛盾。从作者那儿回来的那条边带着 return 角色，那是唯一一个会改变线怎么画的角色：一个空心箭头，于是读者不必去追踪就看见这个回路闭合了。" },
  "WorkflowFigure/03-three-structures-on-one-grid": { hash: 'ed61f920', zh: "泳道回答「谁」，页眉线上的阶段说明回答「什么时候」，而分组框回答「范围里有什么」——一张栅格上的三种结构，因为一份操作手册会被三种不同的人为着这三个问题去读。那个框是虚线的，因为这一组带着 security 变体，而那是这张图上唯一一个读者不用追箭头就能核查的断言。那份回执离开主路径、画成虚线而不是实线，而这正是「一封可能会晚到的邮件」和「一批不能晚到的货」之间的全部差别。" },
  "WorkflowFigure/04-what-a-role-draws": { hash: 'c5554165', zh: "同一次部署上的四种边角色，每一种都配上了绘制它的那个 variant。role 说的是一条线的含义，而渲染器只读它其中一个取值——return，为了那个空心箭头——所以 branch、async 和 error 单靠自己不会改变描边的任何东西。一条留在默认 variant 上的 error 边，会按正常路径的分量和实心程度画出来，而那恰恰是一份操作手册绝不能做的事。泳道的尺寸也是照它装的东西定的，所以一条空泳道不会充当间隔——它会塌成挨着栏沟的大约一列宽，名字还在上面。" },
}

/**
 * The Chinese for one example description, or the English to fall back to.
 *
 * Never returns a translation whose fingerprint has gone stale — the test is
 * the guard, but a build that somehow shipped one should still show the English
 * rather than a sentence about how the example used to behave. Falling back to
 * the English is always right here; falling back to nothing never is, because
 * the sentence is the only thing on the page that says what the example is for.
 */
export function exampleCopy(locale: Locale, key: string, english: string): string {
  if (locale !== 'zh') return english
  const entry = EXAMPLE_ZH[key]
  if (!entry) return english
  return entry.hash === fingerprint(english) ? entry.zh : english
}
